Code:
rule MSSP_T1003_CredDump_SensitiveFileArtifact {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects file creation or modification events targeting well-known credential store paths and dump file patterns across Linux, macOS, and Windows. Attackers who dump credentials frequently write output to disk (e.g. LSASS minidumps, SAM/SYSTEM hive exports, /etc/shadow copies, keychains). This rule fires on the resulting file artifact rather than the process command line, providing coverage that survives command-line obfuscation and binary renaming."
    mitre_tactic = "Credential Access"
    mitre_technique = "T1003"
    mitre_technique_name = "OS Credential Dumping"
    log_prerequisites = "Requires EDR file-event telemetry (e.g. CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, Sysmon EventID 11) forwarded to Chronicle via UDM. FILE_CREATION and FILE_MODIFICATION events must include target.file.full_path."
    platform = "Linux, macOS, Windows"
    false_positives = "Legitimate backup agents exporting registry hives (e.g. SCCM, Veeam, Windows Server Backup). Security tooling performing authorised credential audits. macOS Keychain sync processes. Shadow copy creation by backup software. Forensic workstations running authorised IR tooling."
    tuning_guidance = "Add authorised backup agent process paths to %global_allowed_credential_file_writers. Scope exclusions narrowly to the specific process path, not the entire host, to avoid blind spots. Consider adding a parent-process join rule as a follow-on to correlate with suspicious parent lineage."

  events:
    $file.metadata.event_type = "FILE_CREATION"

    // Match sensitive credential file paths and dump artifacts across platforms.
    // Windows: SAM/SYSTEM/SECURITY hive exports, LSASS dump files, NTDS.dit copies,
    //          credential manager exports, LSA secrets dumps.
    // Linux:   /etc/shadow copies, /proc/*/mem reads written to disk, keyrings.
    // macOS:   Keychain database copies, securityd memory dumps.
    (
      // Windows registry hive exports written outside their canonical locations
      $file.target.file.full_path = /\\(SAM|SYSTEM|SECURITY|NTDS\.dit)(\.|$)/ nocase

      or

      // LSASS / process memory dump files by extension or common naming patterns
      $file.target.file.full_path = /\.(dmp|mdmp|dump)$/ nocase

      or

      // NTDS.dit copies anywhere outside the canonical NTDS directory
      (
        $file.target.file.full_path = /ntds\.dit/ nocase
        and not $file.target.file.full_path = /\\Windows\\NTDS\\ntds\.dit/ nocase
      )

      or

      // Linux shadow file written outside /etc
      (
        $file.target.file.full_path = /\/shadow/ nocase
        and not $file.target.file.full_path = /^\/etc\/shadow$/
      )

      or

      // macOS Keychain database copies outside canonical locations
      (
        $file.target.file.full_path = /\.keychain(-db)?$/ nocase
        and not $file.target.file.full_path = /\/Library\/Keychains\// nocase
      )

      or

      // Generic credential dump output naming conventions used by common tooling
      $file.target.file.full_path = /(lsass|cred(ential)?s?|hashdump|sekurlsa|mimikatz|pwdump|fgdump|cachedump|wce_|gsecdump)/ nocase
    )

    // Exclude authorised credential file writers (backup agents, IR tooling allow-listed per customer)
    not $file.principal.process.file.full_path in %global_allowed_credential_file_writers

    // Exclude canonical Windows backup and VSS processes writing hives legitimately
    not $file.principal.process.file.full_path = /\\(svchost\.exe|wbengine\.exe|vssvc\.exe|smss\.exe|lsass\.exe|csrss\.exe)$/ nocase

    // Exclude Windows registry hive files in their canonical system locations
    not (
      $file.target.file.full_path = /\\Windows\\System32\\config\\(SAM|SYSTEM|SECURITY|DEFAULT|SOFTWARE)$/ nocase
    )

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1003")
    $primary_entity = array_distinct($file.principal.hostname)

  condition:
    $file
}

rule MSSP_T1055_001_DLL_Injection_Process_Handle_Request {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a non-system process opening a handle to another process with permissions consistent with DLL injection preparation (PROCESS_VM_WRITE + PROCESS_CREATE_THREAD). Classic DLL injection requires writing a DLL path into the target process virtual address space and then creating a remote thread; both operations require elevated handle rights that are rarely needed by legitimate software against arbitrary third-party processes. This rule pivots on the PROCESS_OPEN telemetry layer rather than command-line arguments, providing additive coverage orthogonal to process-creation rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.001"
    mitre_technique_name = "Process Injection: Dynamic-link Library Injection"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events with target.process.access_mask or equivalent handle-rights field (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint via MDE advanced hunting forwarded to Chronicle, or Sysmon Event ID 10 ingested via Chronicle Sysmon parser)."
    platform = "Windows"
    false_positives = "Debuggers (WinDbg, x64dbg, Visual Studio debugger), legitimate AV/EDR self-protection probes, process monitoring tools (Process Hacker, Process Explorer), RMM agents performing memory diagnostics, JVM/CLR runtimes performing cross-process optimisation."
    tuning_guidance = "Add known debugger and monitoring tool paths to %global_allowed_process_open_tools. Add known RMM agent paths to %global_allowed_rmm_agents. Consider narrowing by requiring the opening process to reside outside of %windir% and %programfiles% if your EDR populates principal.process.file.full_path reliably."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opening (injecting) process must NOT be a known Windows system binary.
    // Legitimate OS components rarely need cross-process VM_WRITE + CREATE_THREAD rights.
    not $open.principal.process.file.full_path = /\\windows\\system32\\/  nocase
    not $open.principal.process.file.full_path = /\\windows\\syswow64\\/ nocase
    not $open.principal.process.file.full_path = /\\windows\\sysnative\\/ nocase

    // The target process should not be the same process (self-injection is a separate technique).
    // Chronicle populates principal PID vs target PID; where available, exclude self-opens.
    // We approximate by ensuring the target process path differs from the opener.
    not $open.target.process.file.full_path = $open.principal.process.file.full_path

    // The target must be a running user-mode process (not an idle/system PID placeholder).
    $open.target.process.file.full_path = /\.exe$/  nocase

    // Access mask pattern: DLL injection requires at minimum PROCESS_VM_WRITE (0x0020),
    // PROCESS_VM_OPERATION (0x0008), and PROCESS_CREATE_THREAD (0x0002).
    // Many EDRs surface the access mask as a hex string or integer in the command_line
    // or a dedicated field. Match the combined mask value 0x43A (PROCESS_ALL_ACCESS subsets)
    // or the common shorthand masks seen in injection frameworks.
    // We match on the access_mask field where populated, and fall back to command_line
    // representation emitted by Sysmon (GrantedAccess field forwarded as command_line context).
    (
      $open.target.process.command_line = /0x[0-9a-f]*[13][0-9a-f]{2,}/  nocase
      or
      $open.target.process.command_line = /GrantedAccess.*0x[0-9a-f]*(1f|43|23|3[89a-f])/  nocase
    )

    // Exclude known-safe openers via reference list (MSSP multi-tenant tuning).
    not $open.principal.process.file.full_path in %global_allowed_process_open_tools
    not $open.principal.process.file.full_path in %global_allowed_rmm_agents

    // Exclude processes opening themselves or system idle.
    $open.principal.process.pid != 0
    $open.target.process.pid != 0
    $open.principal.process.pid != $open.target.process.pid

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.001")
    $primary_entity = array_distinct($open.principal.hostname)
    $opening_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opening_user = array_distinct($open.principal.user.userid)

  condition:
    $open
}

rule MSSP_T1055_001_ProcessOpen_Then_RemoteThread_DLL_Injection {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Sequence"
    severity = "High"
    description = "Detects the two-stage DLL injection pattern: a non-system process opens a handle to a remote process (PROCESS_OPEN) and then a new thread is created in that target process (PROCESS_INJECTION) within 5 minutes. This covers the VirtualAllocEx/WriteProcessMemory/CreateRemoteThread injection chain without relying on command-line strings, providing additive coverage beyond existing PROCESS_LAUNCH rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.001"
    mitre_technique_name = "Process Injection: Dynamic-link Library Injection"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events (e.g., Sysmon Event ID 10 - ProcessAccess) and PROCESS_INJECTION events (e.g., Sysmon Event ID 8 - CreateRemoteThread). Both event types must be ingested into Chronicle UDM."
    platform = "Windows"
    false_positives = "Legitimate debuggers (WinDbg, Visual Studio), AV/EDR products performing process inspection, RMM agents (e.g., CrowdStrike, SentinelOne self-protection), JIT compilers, and software installers that inject into host processes."
    tuning_guidance = "Add known-good opener processes (debuggers, EDR agents) to %global_allowed_process_openers. Add known-good target processes that are routinely injected into by legitimate software to %global_allowed_injection_targets. Consider scoping by asset criticality tier."

  events:
    // Stage 1: A non-system process opens a handle to another process.
    // Sysmon Event 10 (ProcessAccess) maps to PROCESS_OPEN in UDM.
    // principal = the process opening the handle; target = the victim process.
    $open.metadata.event_type = "PROCESS_OPEN"

    // Exclude common system paths that legitimately open process handles at high volume.
    not $open.principal.process.file.full_path = /\\(svchost|lsass|csrss|wininit|services|smss)\.exe$/ nocase
    not $open.principal.process.file.full_path = /\\Windows\\(System32|SysWOW64)\\/ nocase

    // Require the opener to be a user-space or suspicious-path process.
    $open.principal.process.file.full_path = /\.(exe|dll|scr|com)$/ nocase

    // Exclude known-good openers via reference list (EDR agents, debuggers, RMM).
    not $open.principal.process.file.full_path in %global_allowed_process_openers

    // Exclude known-good injection targets via reference list.
    not $open.target.process.file.full_path in %global_allowed_injection_targets

    // Capture the hostname to join both events to the same machine.
    $open.principal.hostname = $hostname

    // Capture the opener process path to correlate with the injection event.
    $open.principal.process.file.full_path = $opener_path

    // Stage 2: A remote thread is created in a target process on the same host.
    // Sysmon Event 8 (CreateRemoteThread) maps to PROCESS_INJECTION in UDM.
    // principal = the injecting process; target = the process receiving the thread.
    $inj.metadata.event_type = "PROCESS_INJECTION"

    // The injecting process must be the same binary that opened the handle.
    $inj.principal.process.file.full_path = $opener_path

    // Exclude self-injection (same PID) - legitimate for some runtimes.
    // Require the injection to target a different process (cross-process).
    not $inj.principal.process.file.full_path = $inj.target.process.file.full_path

    // Exclude known-good injection targets on the injection side as well.
    not $inj.target.process.file.full_path in %global_allowed_injection_targets

    // Exclude known-good openers on the injection side as well.
    not $inj.principal.process.file.full_path in %global_allowed_process_openers

    $inj.principal.hostname = $hostname

    // Enforce chronological ordering: handle open must precede thread creation.
    $open.metadata.event_timestamp.seconds <= $inj.metadata.event_timestamp.seconds

  match:
    $hostname, $opener_path over 5m

  outcome:
    $risk_score = max(85)
    $mitre_technique_id = array_distinct("T1055.001")
    $primary_entity = array_distinct($open.principal.hostname)
    $injecting_process = array_distinct($open.principal.process.file.full_path)
    $target_process_open = array_distinct($open.target.process.file.full_path)
    $target_process_injected = array_distinct($inj.target.process.file.full_path)
    $injecting_user = array_distinct($open.principal.user.userid)
    $open_event_count = count($open.metadata.event_timestamp.seconds)
    $inj_event_count = count($inj.metadata.event_timestamp.seconds)

  condition:
    $open and $inj
}

rule MSSP_T1055_002_PE_Injection_Process_Handle_Open {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects suspicious cross-process handle acquisition consistent with PE injection preparation. Adversaries performing T1055.002 must first open a handle to the target process with PROCESS_VM_WRITE and PROCESS_CREATE_THREAD access rights before calling VirtualAllocEx/WriteProcessMemory/CreateRemoteThread. This rule fires on PROCESS_OPEN events where a non-standard process requests those combined access rights against a high-value system process, catching the state change that precedes the actual injection without relying on command-line telemetry."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.002"
    mitre_technique_name = "Process Injection: Portable Executable Injection"
    log_prerequisites = "Requires EDR telemetry that surfaces PROCESS_OPEN events with target process name and requested access mask (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, or Sysmon Event ID 10 ingested via Chronicle UDM). The target.process.file.full_path and principal.process.file.full_path fields must be populated."
    platform = "Windows"
    false_positives = "Legitimate debuggers (WinDbg, x64dbg, Visual Studio debugger), AV/EDR self-protection handles, process monitoring tools (Process Hacker, Process Explorer), JIT compilers (CLR, JVM) opening handles to their own child processes, and some RMM agents. Tune using the exclusion lists below."
    tuning_guidance = "Add known-good opener process paths to %global_allowed_process_openers (e.g., debuggers, AV engines, RMM agents). Add approved target process paths to %global_allowed_injection_targets if a specific pairing is a confirmed false positive. Consider narrowing by principal.user.userid to exclude dedicated service accounts."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opener (principal) must NOT be a well-known system process that
    // legitimately opens handles to other processes. Regex anchored to
    // filename to survive path variation.
    not $open.principal.process.file.full_path = /\\(lsass|csrss|smss|wininit|services|svchost|MsMpEng|SenseIR|SenseCncProxy|MsSense|elastic-endpoint)\.exe$/ nocase

    // Target must be a high-value system process that adversaries commonly
    // inject into for privilege escalation or AV evasion.
    $open.target.process.file.full_path = /\\(lsass|svchost|explorer|winlogon|csrss|spoolsv|dllhost|RuntimeBroker|SearchIndexer|taskhostw|sihost)\.exe$/ nocase

    // The opener must not be the same binary as the target (self-handle).
    // Chronicle does not support field-to-field comparison directly, so we
    // exclude the most common self-open pattern: svchost opening svchost.
    // Broader self-open suppression is handled by the exclusion list.
    not $open.principal.process.file.full_path = /\\svchost\.exe$/ nocase

    // Opener must not reside in well-known AV / EDR / system directories.
    not $open.principal.process.file.full_path = /\\(Program Files|Program Files \(x86\))\\(Windows Defender|CrowdStrike|SentinelOne|Carbon Black|Cylance|Sophos|ESET|Trend Micro|McAfee|Symantec|Malwarebytes|Elastic)\\/ nocase

    // Opener must not reside in the Windows system directories (legitimate OS components).
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww]indows\\[Ss]ystem32\\/ nocase
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww]indows\\[Ss]ys[Ww][Oo][Ww]64\\/ nocase

    // Exclude known-good openers via reference list (MSSP tuning hook).
    not $open.principal.process.file.full_path in %global_allowed_process_openers

    // Exclude known-good target pairings via reference list.
    not $open.target.process.file.full_path in %global_allowed_injection_targets

    // Require the opener to have a resolvable hostname (filters noise/incomplete events).
    $open.principal.hostname != ""

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.002")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opener_user = array_distinct($open.principal.user.userid)

  condition:
    $open
}

rule MSSP_T1055_003_Thread_Hijack_Process_Open_Handle {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects PROCESS_OPEN events where an unexpected process requests a handle to another process with thread-manipulation-capable access rights. Thread Execution Hijacking (T1055.003) requires OpenThread/OpenProcess with rights sufficient to suspend, write, and resume a thread. This rule fires on the handle acquisition event itself rather than on command-line telemetry, providing a complementary detection layer that is harder for attackers to suppress."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.003"
    mitre_technique_name = "Process Injection: Thread Execution Hijacking"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events with target.process.file.full_path and principal.process.file.full_path populated. Sysmon Event ID 10 (ProcessAccess) mapped to UDM PROCESS_OPEN is the primary source. The access mask field should be mapped to a UDM extension or security_result field if available."
    platform = "Windows"
    false_positives = "Debuggers (Visual Studio, WinDbg, x64dbg), legitimate AV/EDR self-protection handles, JIT compilers (JVM, CLR), crash-reporting agents (WerFault), RMM agents performing process inspection, and profiling tools. Tune aggressively using the reference lists below."
    tuning_guidance = "Add known-good opener binaries (full path) to %global_allowed_process_openers. Add known-good target process names to %global_allowed_process_open_targets. Consider narrowing to non-system32 openers first to reduce volume in noisy environments."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opener (principal) must NOT be a well-known system process that
    // legitimately opens handles to other processes for benign reasons.
    // We match on processes outside the canonical Windows system directories
    // OR on scripting hosts that should never be opening arbitrary process handles.
    (
      not $open.principal.process.file.full_path = /\\(windows\\system32|windows\\syswow64|windows\\sysnative)\\/ nocase
      or
      $open.principal.process.file.full_path = /\\(powershell|pwsh|wscript|cscript|mshta|rundll32|regsvr32|msiexec|wmic|cmd)\.exe$/ nocase
    )

    // Target must be a running process that is a plausible hijack victim:
    // system services, browsers, or other long-lived processes.
    // We exclude self-opens (same process opening itself) by requiring the
    // target to be a different well-known host process.
    $open.target.process.file.full_path = /\\(svchost|lsass|explorer|RuntimeBroker|SearchHost|SearchIndexer|spoolsv|winlogon|csrss|services|dllhost|taskhost|taskhostw|sihost|ctfmon|audiodg|chrome|msedge|firefox|iexplore)\.exe$/ nocase

    // Exclude the opener being the same binary as the target (self-inspection
    // patterns used by browsers and runtimes).
    not $open.principal.process.file.full_path = $open.target.process.file.full_path

    // Exclude known-good opener binaries supplied per-customer.
    not $open.principal.process.file.full_path in %global_allowed_process_openers

    // Exclude known-good target processes that are routinely inspected in
    // this environment (e.g., a customer's own monitoring agent opening svchost).
    not $open.target.process.file.full_path in %global_allowed_process_open_targets

    // Exclude openers running from user-writable temp paths that are already
    // caught by other rules (avoid double-alerting on the noisier path).
    not $open.principal.process.file.full_path = /\\(appdata|programdata|temp|tmp)\\/ nocase

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1055.003")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opener_pid = array_distinct($open.principal.process.pid)
    $target_pid = array_distinct($open.target.process.pid)

  condition:
    $open
}

rule MSSP_T1055_004_APC_Injection_Process_Handle_Open {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects PROCESS_OPEN events where a process requests thread-level access rights consistent with APC injection (OpenThread / NtQueueApcThread patterns). Attackers performing APC injection must first obtain a handle to a target thread with THREAD_SET_CONTEXT or THREAD_GET_CONTEXT rights before queuing the APC. This rule fires on the resulting handle-open telemetry rather than command-line arguments, providing coverage that is orthogonal to process-creation rules and harder for attackers to suppress."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.004"
    mitre_technique_name = "Process Injection: Asynchronous Procedure Call"
    log_prerequisites = "Requires EDR telemetry that records PROCESS_OPEN / thread-open events with the requested access mask and the calling process path. Sysmon Event ID 10 (ProcessAccess) with GrantedAccess populated, or a compatible EDR source ingested as UDM PROCESS_OPEN, is required."
    platform = "Windows"
    false_positives = "Debuggers (WinDbg, x64dbg, Visual Studio debugger), profiling tools (VTune, dotTrace), legitimate AV/EDR self-protection hooks, crash-dump collectors (WerFault), and some RMM agents that enumerate thread state."
    tuning_guidance = "Add known-good callers (debuggers, AV engines, RMM agents) to %global_allowed_thread_openers. Narrow further by pairing with a cross-process memory-write event on the same host within a short window. Consider raising severity when the calling process is itself a short-lived or unsigned binary."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Caller must NOT be a known system process performing legitimate thread inspection.
    // Legitimate callers are excluded via reference list; what remains are unexpected openers.
    not $open.principal.process.file.full_path in %global_allowed_thread_openers

    // The calling process should not be a native Windows component under System32
    // performing routine work. We flag callers outside the canonical system paths
    // OR callers that are interpreters/scripting hosts (high-risk LOLBins).
    (
      not $open.principal.process.file.full_path = /\\Windows\\System32\\/  nocase
      or $open.principal.process.file.full_path = /\\(powershell|pwsh|wscript|cscript|mshta|rundll32|regsvr32|msiexec|wmic|certutil|bitsadmin|installutil|regasm|regsvcs|msbuild|cmstp|xwizard|syncappvpublishingserver)\.exe$/  nocase
    )

    // Target must be a process other than the caller itself (cross-process injection).
    // Self-opens are routine; cross-process opens with thread-level rights are suspicious.
    $open.principal.process.pid != $open.target.process.pid

    // Target process is a high-value injection target: a running user-mode process.
    // We look for well-known host processes that adversaries commonly inject into.
    // Broad enough to avoid hardcoding attacker tooling; narrow enough to reduce noise.
    (
      $open.target.process.file.full_path = /\\(svchost|lsass|explorer|RuntimeBroker|SearchHost|SearchIndexer|spoolsv|winlogon|csrss|dllhost|taskhost|taskhostw|sihost|ctfmon|dwm|wininit|services|smss)\.exe$/ nocase
      or $open.target.process.file.full_path = /\\(msedge|chrome|firefox|iexplore|MicrosoftEdge)\.exe$/ nocase
    )

    // The requested access mask should include thread-manipulation rights.
    // THREAD_SET_CONTEXT (0x0010) is required for QueueUserAPC.
    // THREAD_GET_CONTEXT (0x0008) is required for Early Bird / suspended-process variants.
    // Chronicle surfaces this in target.process.access_mask when the EDR populates it.
    // We match on the hex string representation as populated by Sysmon/EDR UDM mapping.
    (
      $open.target.process.access_mask = /0x001[0-9a-fA-F]/ nocase
      or $open.target.process.access_mask = /0x0[0-9a-fA-F][1-9a-fA-F][0-9a-fA-F]/ nocase
      or $open.target.process.access_mask = /0x1[fF]3[aA]/ nocase
      or $open.target.process.access_mask = /0x1[fF]0[0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]/ nocase
    )

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.004")
    $primary_entity = array_distinct($open.principal.hostname)

  condition:
    $open
}

rule MSSP_T1055_005_TLS_Injection_Process_Handle_Request {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects suspicious cross-process handle acquisition with VM_WRITE and VM_OPERATION access rights, a prerequisite for TLS callback injection. Attackers must open a handle to the target process with these rights before manipulating PE memory structures to redirect TLS callbacks. This rule fires on the PROCESS_OPEN event rather than command-line telemetry, providing a lower-level and harder-to-evade signal."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.005"
    mitre_technique_name = "Process Injection: Thread Local Storage"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events with requested access rights (e.g., CrowdStrike Falcon, Microsoft Defender for Endpoint, Carbon Black, Sysmon Event ID 10). The access_mask or equivalent field must be populated. Chronicle UDM field: target.process.access_mask or security_result.rule_labels."
    platform = "Windows"
    false_positives = "Debuggers (WinDbg, x64dbg, Visual Studio), legitimate process monitoring tools, AV/EDR self-protection, RMM agents performing process inspection, crash dump utilities (ProcDump), and software installers that inject into running processes for patching."
    tuning_guidance = "Populate %global_allowed_process_openers with full paths of approved debuggers, RMM agents, and AV/EDR binaries. Populate %global_allowed_target_processes with paths of processes that are legitimately opened by admin tooling. Narrow scope further by correlating with unusual parent lineage or non-standard install paths."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Opener must NOT be a known system process performing legitimate cross-process work.
    // Match processes opening from non-standard or user-writable locations.
    // Legitimate system openers (lsass, csrss, services.exe) are excluded via reference list.
    not $open.principal.process.file.full_path in %global_allowed_process_openers

    // Target should be a running host process - exclude self-opens and kernel paths.
    // Attackers target long-lived host processes (explorer, svchost, etc.) for TLS injection.
    $open.target.process.file.full_path != ""
    not $open.target.process.file.full_path in %global_allowed_target_processes

    // Opener originates from a user-writable or non-standard path, a strong signal of
    // a dropped/injected binary performing the handle request.
    // Match paths under Users, Temp, AppData, ProgramData, or with no fixed install root.
    $open.principal.process.file.full_path = /\\(users|temp|tmp|appdata|programdata|downloads|public)\\/ nocase

    // The target process should be a commonly abused host process for injection.
    // Broad regex to catch svchost, explorer, lsass, RuntimeBroker, etc.
    $open.target.process.file.full_path = /\\(svchost|explorer|lsass|RuntimeBroker|dllhost|taskhost|taskhostw|spoolsv|winlogon|csrss|wininit|services)\.exe$/ nocase

    // Exclude cases where opener and target are the same binary (self-open is benign).
    $open.principal.process.file.full_path != $open.target.process.file.full_path

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.005")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opener_pid = array_distinct($open.principal.process.pid)
    $target_pid = array_distinct($open.target.process.pid)

  condition:
    $open
}

rule MSSP_T1055_008_Ptrace_Injection_Process_Open {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a non-debugger process opening a handle to another running process with ptrace-compatible access, which is the OS-level artifact produced when ptrace system call injection occurs. An attacker attaches to a live process to write shellcode into its address space. This rule fires on the PROCESS_OPEN event rather than command-line telemetry, providing a distinct detection layer that survives binary renaming and argument obfuscation."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.008"
    mitre_technique_name = "Process Injection: Ptrace System Calls"
    log_prerequisites = "Requires an EDR or eBPF-based sensor that emits PROCESS_OPEN (process handle acquisition) events on Linux, e.g. Elastic Defend, Falco with Chronicle forwarder, or CrowdStrike Falcon with process-open telemetry enabled."
    platform = "Linux"
    false_positives = "Legitimate debuggers (gdb, lldb, strace, ltrace), Java/Python profilers, crash-dump collectors (breakpad, sentry-native), container runtimes performing live introspection, and security agents that self-inspect. Tune via %linux_allowed_ptrace_parents."
    tuning_guidance = "Populate %linux_allowed_ptrace_parents with full paths of approved debuggers and profiling agents (e.g. /usr/bin/gdb, /usr/bin/strace). Add monitoring/observability service accounts to %linux_allowed_ptrace_users. Consider scoping to interactive user sessions by excluding principal.user.userid matching service account patterns."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The opening (attaching) process must NOT be a known legitimate debugger.
    // Regex matches common debugger/tracer binary names; exclusion list handles
    // site-specific approved tools.
    not $open.principal.process.file.full_path = /\/(gdb|lldb|strace|ltrace|perf|valgrind|rr|gdbserver|lldb-server|debuginfod|java|python[23]?|ruby|node|dotnet)$/ nocase
    not $open.principal.process.file.full_path in %linux_allowed_ptrace_parents

    // Exclude kernel threads and init (pid 1 / kthreadd patterns).
    not $open.principal.process.file.full_path = /^\[/ nocase

    // The target process must be a different process (cross-process open).
    // Exclude self-opens: principal and target process paths differ.
    // We cannot compare two fields directly in YARA-L, so we exclude the
    // common self-open pattern where the target is the same binary.
    not $open.target.process.file.full_path = $open.principal.process.file.full_path

    // Exclude root-to-root opens that are part of normal system management
    // only when the opener is a known system daemon path.
    not $open.principal.process.file.full_path = /^\/(usr\/)?s?bin\/(systemd|dockerd|containerd|kubelet|snapd|auditd|sshd|crond|rsyslogd)$/ nocase

    // Exclude approved service account users performing legitimate introspection.
    not $open.principal.user.userid in %linux_allowed_ptrace_users

    // Require a real user context - filter out pure kernel-space events.
    $open.principal.user.userid != ""

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.008")
    $primary_entity = array_distinct($open.principal.hostname)
    $attaching_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $acting_user = array_distinct($open.principal.user.userid)

  condition:
    $open
}

rule MSSP_T1055_011_EWM_Injection_Process_Handle_Request {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects suspicious process handle acquisition targeting GUI/graphical processes that are commonly abused for Extra Window Memory (EWM) injection. Attackers open a handle to a target process hosting a registered window class, write shellcode into a shared section, update the EWM pointer via SetWindowLong/SetWindowLongPtr, and redirect execution. This rule pivots on the PROCESS_OPEN telemetry layer rather than command-line arguments, providing additive coverage orthogonal to process-creation rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.011"
    mitre_technique_name = "Process Injection: Extra Window Memory Injection"
    log_prerequisites = "Requires EDR telemetry that records process handle open events (e.g., Sysmon Event ID 10 / CrowdStrike process open telemetry). The access rights bitmask must be populated in the UDM field target.process.access_mask or an equivalent mapped field. Sysmon must be configured with ProcessAccess rules targeting GUI host processes."
    platform = "Windows"
    false_positives = "Legitimate accessibility tools (e.g., screen readers, magnifiers), remote desktop agents, UI automation frameworks (e.g., Selenium, WinAppDriver), debugging tools (WinDbg, x64dbg), and some AV/EDR self-protection handles. Correlate with parent process lineage and time-of-day before escalating."
    tuning_guidance = "Add known-good automation or accessibility tool paths to %global_allowed_process_openers. Narrow scope by requiring the opening process to originate outside %global_allowed_admin_tool_paths. Consider pairing with a subsequent REGISTRY_MODIFICATION or NETWORK_CONNECTION rule for higher-fidelity sequencing."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Target must be a GUI host process commonly registered with window classes
    // and therefore carrying EWM. Regex covers the canonical targets without
    // hardcoding a single binary name, surviving attacker renaming of injector.
    $open.target.process.file.full_path = /\\(explorer|dwm|winlogon|csrss|lsass|svchost|RuntimeBroker|ShellExperienceHost|SearchHost|StartMenuExperienceHost|sihost|taskhostw|ctfmon|dllhost)\.exe$/ nocase

    // Opening process must NOT be a known-good system parent.
    // Legitimate OS components opening handles to these processes use
    // well-known, stable paths; suspicious openers typically live in
    // user-writable or temp directories.
    $open.principal.process.file.full_path = /\\(users|appdata|temp|tmp|programdata|public)/i nocase

    // Exclude known-good opener paths supplied via reference list.
    not $open.principal.process.file.full_path in %global_allowed_process_openers

    // Exclude known-good admin tool paths (RMM agents, AV, EDR self-handles).
    not $open.principal.process.file.full_path in %global_allowed_admin_tool_paths

    // The opening process must not itself be a recognised system binary
    // (prevents noisy OS-internal handle traffic from firing).
    not $open.principal.process.file.full_path = /\\(svchost|services|wininit|smss|lsass|csrss|winlogon|explorer|MsMpEng|SenseIR|SenseCncProxy)\.exe$/ nocase

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.011")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $target_pid = array_distinct($open.target.process.pid)

  condition:
    $open
}

rule MSSP_T1055_012_Process_Hollowing_Suspended_Process_Open {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a process opening a handle to another process with PROCESS_VM_WRITE and PROCESS_VM_OPERATION access rights combined with PROCESS_SUSPEND_RESUME, which is the canonical handle-request pattern produced by process hollowing. The injecting process creates a victim in suspended state, then opens it with these rights to unmap, rewrite, and resume it. This rule fires on the PROCESS_OPEN telemetry produced by EDR sensors (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint) that surface cross-process handle requests, providing coverage orthogonal to command-line/process-launch rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.012"
    mitre_technique_name = "Process Injection: Process Hollowing"
    log_prerequisites = "Requires EDR telemetry that surfaces PROCESS_OPEN events with granted_access bitmask or equivalent access-rights field (e.g., CrowdStrike ProcessRollup2 with handle grants, SentinelOne cross-process events, MDE DeviceEvents ActionType=OpenProcess). The UDM field target.process.access_mask or an equivalent mapped field must be populated."
    platform = "Windows"
    false_positives = "Legitimate debuggers (WinDbg, x64dbg, Visual Studio debugger), process monitors (Process Hacker, Process Explorer), some AV/EDR self-protection drivers opening their own protected processes, JVM/CLR runtimes that suspend threads for GC, and certain RMM agents. Scope exclusions using %global_allowed_process_open_parents."
    tuning_guidance = "Add known-good parent process paths (debuggers, RMM agents, AV engines) to %global_allowed_process_open_parents. Add known-good target process paths (e.g., JVM, CLR hosts) to %global_allowed_hollow_targets. Consider raising severity to Critical if the opening process is not a signed Microsoft binary."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The hollowing workflow requires the injector to open the victim with
    // at minimum: PROCESS_VM_WRITE (0x0020), PROCESS_VM_OPERATION (0x0008),
    // and PROCESS_SUSPEND_RESUME (0x0800).  Many EDR vendors map these into
    // a combined access mask.  We match the three most diagnostic rights
    // individually so the rule fires even when additional bits are set.
    // Access mask 0x1fffff = PROCESS_ALL_ACCESS; 0x0828 = VM_WRITE |
    // VM_OPERATION | SUSPEND_RESUME without PROCESS_ALL_ACCESS.
    // We detect the suspicious combination via the target process being
    // a known Windows host process opened by an unexpected parent.

    // Target must be a legitimate Windows host process commonly used as a
    // hollowing victim (svchost, RuntimeBroker, dllhost, msiexec, etc.)
    $open.target.process.file.full_path = /\\(svchost|RuntimeBroker|dllhost|msiexec|werfault|conhost|spoolsv|lsass|taskhost|taskhostw|sihost|ctfmon|SearchIndexer|WmiPrvSE|regsvr32|rundll32|mshta|wscript|cscript|explorer)\.exe$/i nocase

    // The opening (injecting) process must NOT itself be one of the
    // canonical Windows parents for the target — that is the anomaly.
    // Legitimate svchost parents are services.exe / wininit.exe, etc.
    not $open.principal.process.file.full_path = /\\(services|wininit|smss|csrss|winlogon|lsass|wininit)\.exe$/ nocase

    // Exclude known-good tooling via reference lists
    not $open.principal.process.file.full_path in %global_allowed_process_open_parents
    not $open.target.process.file.full_path in %global_allowed_hollow_targets

    // Exclude self-opens (process opening itself — normal for many runtimes)
    not $open.principal.process.pid = $open.target.process.pid

    // The opening process should not reside in a trusted system directory
    // (attackers stage from user-writable paths)
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww][Ii][Nn][Dd][Oo][Ww][Ss]\\[Ss]ystem32\\/ nocase
    not $open.principal.process.file.full_path = /^[Cc]:\\[Ww][Ii][Nn][Dd][Oo][Ww][Ss]\\[Ss]ys[Ww][Oo][Ww]64\\/ nocase
    not $open.principal.process.file.full_path = /^[Cc]:\\[Pp]rogram [Ff]iles\\/ nocase
    not $open.principal.process.file.full_path = /^[Cc]:\\[Pp]rogram [Ff]iles \([Xx]86\)\\/ nocase

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.012")
    $primary_entity = array_distinct($open.principal.hostname)
    $opening_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opening_user = array_distinct($open.principal.user.userid)

  condition:
    $open
}

rule MSSP_T1055_012_Hollowed_Process_Anomalous_Network_After_Suspend {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Sequence"
    severity = "High"
    description = "Detects a hallmark of process hollowing: a legitimate Windows binary is launched suspended (PROCESS_OPEN targeting a known-good host process) and then that same process makes an outbound network connection shortly after. The combination of a cross-process handle acquisition followed by unexpected network activity from a normally non-networking binary is a strong behavioral indicator of a hollowed process being used as a network beachhead."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.012"
    mitre_technique_name = "Process Injection: Process Hollowing"
    log_prerequisites = "Requires EDR telemetry that logs PROCESS_OPEN (cross-process handle) events and NETWORK_CONNECTION events with process context. Sysmon EventID 10 (ProcessAccess) and EventID 3 (NetworkConnect) satisfy this. CrowdStrike Falcon and SentinelOne also emit equivalent UDM events."
    platform = "Windows"
    false_positives = "Legitimate debuggers (Visual Studio, WinDbg) opening handles to child processes. Software update agents that spawn helper processes. JIT compilers (CLR, JVM) that manipulate child process memory. Crash-reporting tools. Security products performing process inspection."
    tuning_guidance = "Add known-safe parent processes (e.g. Visual Studio devenv.exe, JetBrains IDEs, crash reporters) to %hollowing_allowed_openers. Add known-safe network-capable binaries that may be legitimately hollowed by benign tooling to %hollowing_allowed_network_hosts. Scope by environment: developer workstations will generate more FPs than servers."

  events:
    // Leg 1: A process opens a handle to a victim process that is a known
    // Windows host binary (these are the canonical hollowing targets because
    // they are signed, trusted, and blend in). PROCESS_OPEN captures the
    // cross-process handle acquisition that precedes memory unmapping.
    $open.metadata.event_type = "PROCESS_OPEN"
    // Target must be a canonical hollowing victim: a signed Windows binary
    // that would normally not initiate network connections on its own.
    $open.target.process.file.full_path = /\\(svchost|RuntimeBroker|dllhost|taskhost|taskhostw|werfault|SearchIndexer|spoolsv|lsass|services|explorer|notepad|calc|mspaint|msiexec|regsvr32|rundll32|wscript|cscript|conhost|sihost|ctfmon)\.exe$/ nocase
    // The opener must NOT be a known-safe system parent (e.g. services.exe
    // legitimately opens svchost). Exclude the most common benign openers.
    not $open.principal.process.file.full_path = /\\(services|wininit|smss|csrss|lsass|svchost|MsMpEng|SenseIR|SenseCncProxy|CylanceSvc|CbDefense|falconctl|bdagent)\.exe$/ nocase
    not $open.principal.process.file.full_path in %hollowing_allowed_openers
    $open.principal.hostname = $hostname

    // Leg 2: The same victim binary (now hollowed) makes an outbound network
    // connection. We match on the target process path to tie back to the
    // same binary that was opened in leg 1.
    $net.metadata.event_type = "NETWORK_CONNECTION"
    // The networking process must be one of the same canonical victim binaries.
    $net.principal.process.file.full_path = /\\(svchost|RuntimeBroker|dllhost|taskhost|taskhostw|werfault|SearchIndexer|spoolsv|lsass|services|explorer|notepad|calc|mspaint|msiexec|regsvr32|rundll32|wscript|cscript|conhost|sihost|ctfmon)\.exe$/ nocase
    // Exclude RFC-1918 and loopback to focus on external C2 connections.
    // svchost legitimately connects internally; external connections are suspicious.
    not $net.target.ip in %rfc1918_internal
    not $net.target.ip in %hollowing_allowed_network_hosts
    $net.principal.hostname = $hostname

    // Chronological ordering: handle acquisition must precede network activity.
    $open.metadata.event_timestamp.seconds <= $net.metadata.event_timestamp.seconds

  match:
    $hostname over 5m

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.012")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $victim_process = array_distinct($open.target.process.file.full_path)
    $destination_ips = array_distinct($net.target.ip)
    $destination_ports = array_distinct($net.target.port)
    $event_count = count($net.metadata.event_timestamp.seconds)

  condition:
    $open and $net
}

rule MSSP_T1055_013_Doppelganging_TxF_Process_Handle_Open {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects process doppelgänging at the PROCESS_OPEN abstraction layer. Process doppelgänging abuses Windows Transactional NTFS (TxF) to load a malicious image into a legitimate process section. A key observable is a non-privileged or unexpected process opening a handle to another process with VM_WRITE or PROCESS_VM_WRITE access rights, which is required to overwrite the target process memory with the transacted (malicious) image. This rule fires when a process outside of known system and security tooling opens a handle to a remote process, providing coverage orthogonal to command-line / PROCESS_LAUNCH detections."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.013"
    mitre_technique_name = "Process Injection: Process Doppelgänging"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events with target process path and access rights (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint via MDE advanced hunting forwarded to Chronicle, or Sysmon Event ID 10 with GrantedAccess field mapped to UDM)."
    platform = "Windows"
    false_positives = "Security software (AV/EDR agents), debuggers (WinDbg, x64dbg), process monitoring utilities (Process Explorer, Process Hacker), software installers performing in-memory patching, JIT compilers, and legitimate virtualisation or sandboxing products."
    tuning_guidance = "Populate %global_allowed_process_open_sources with full paths of approved security tools, debuggers, and deployment agents (e.g., /windows/system32/msiexec.exe, EDR agent paths). Populate %global_allowed_system_processes with paths of OS processes that legitimately open cross-process handles. Narrow further by correlating with the absence of a signed parent or by restricting to non-system sessions."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // The requesting (principal) process must NOT be a known Windows system binary
    // that legitimately opens cross-process handles. Regex anchors to the filename
    // to avoid path-manipulation bypasses.
    not $open.principal.process.file.full_path = /\\(lsass|csrss|smss|wininit|services|svchost|MsMpEng|SenseIr|MsSense|SecurityHealthService)\.exe$/i nocase
    not $open.principal.process.file.full_path = /\\(WerFault|werfaultsecure|taskmgr|msiexec|TiWorker|TrustedInstaller)\.exe$/ nocase

    // Target process is a legitimate Windows executable - doppelgänging hijacks
    // a real process image to hide malicious code inside it.
    $open.target.process.file.full_path = /\\windows\\/  nocase

    // The target process is NOT the same as the requesting process (no self-open).
    // We approximate this by requiring the target to be a different binary name.
    // Self-opens are common and benign; cross-process opens with write access are not.
    not $open.target.process.file.full_path = $open.principal.process.file.full_path

    // Access rights field: detect VM_WRITE-class access. Chronicle maps Sysmon
    // GrantedAccess into target.process.access_mask (hex string) where available.
    // 0x0020 = PROCESS_VM_WRITE, 0x0008 = PROCESS_VM_OPERATION.
    // We match on the presence of these bits expressed as common combined masks
    // seen in injection tooling (0x1fffff = all-access, 0x0028, 0x1f0fff, etc.).
    // Regex covers the most common combined access masks used by injection frameworks.
    $open.target.process.access_mask = /0x(001f0fff|0028|0020|1fffff|00[0-9a-f]{2}2[08])/  nocase

    // Exclude processes whose full path is in the MSSP-managed allow-list.
    not $open.principal.process.file.full_path in %global_allowed_process_open_sources

    // Exclude known-good target processes that are routinely opened by system components.
    not $open.target.process.file.full_path in %global_allowed_system_processes

    // Requesting process must not reside in the canonical Windows system directories
    // to catch masquerading binaries living outside System32/SysWOW64.
    // NOTE: legitimate injectors (AV) DO live in system32; this filter is intentionally
    // inverted - we KEEP events where the opener is NOT in system32 to reduce FP volume.
    not $open.principal.process.file.full_path = /\\(windows\\system32|windows\\syswow64|windows\\sysnative)\\/  nocase

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1055.013")
    $primary_entity = array_distinct($open.principal.hostname)
    $requesting_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $access_mask_observed = array_distinct($open.target.process.access_mask)

  condition:
    $open
}

rule MSSP_T1055_014_VDSO_Hijack_ProcOpen_Then_AnonExecMap {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Sequence"
    severity = "High"
    description = "Detects a likely VDSO hijacking sequence: a process opens another process's memory (PROCESS_OPEN, consistent with ptrace or /proc/<pid>/mem access) followed shortly after by an anonymous executable memory mapping event on the same host. VDSO hijacking redirects syscall stubs in the target process's vdso region and typically requires opening the victim process before patching the GOT or vdso stubs. The anonymous exec-map event is surfaced by EDR sensors that audit mmap/mprotect calls creating PROT_EXEC regions backed by no file (anonymous). Together these two signals form a high-fidelity behavioural indicator that does not rely on command-line strings and therefore provides additive coverage over existing PROCESS_LAUNCH rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.014"
    mitre_technique_name = "Process Injection: VDSO Hijacking"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events for cross-process memory access (e.g., SentinelOne, CrowdStrike Falcon, Sysdig Falco via UDM ingestion) AND FILE_READ or PROCESS_MODULE_LOAD events annotated with anonymous/memfd executable mappings. Auditd rules for ptrace and mmap syscalls forwarded through the Chronicle Auditd parser also satisfy this requirement."
    platform = "Linux"
    false_positives = "Debuggers (gdb, lldb, strace, perf), JVM/JIT runtimes creating anonymous executable trampolines, Valgrind, sanitizer-instrumented binaries, legitimate profiling agents (Datadog, Dynatrace), and container runtimes that use memfd_create for code generation. Tune using the reference lists below."
    tuning_guidance = "Add known debugger and profiler binary paths to %linux_allowed_proc_openers. Add known JIT runtime binary paths to %linux_allowed_anon_exec_mappers. Scope by principal.hostname to specific high-risk segments if false-positive volume remains elevated."

  events:
    // Leg 1: A process opens another live process's address space.
    // PROCESS_OPEN is emitted by EDR sensors when one process acquires a
    // handle/descriptor to another process (ptrace attach, /proc/<pid>/mem open,
    // process_vm_readv/writev). Pre-filter to non-self opens by requiring
    // distinct process image paths and excluding known-safe openers.
    $open.metadata.event_type = "PROCESS_OPEN"
    $open.principal.process.file.full_path = /\// nocase
    // Exclude self-opens (process opening itself, common in JVM startup)
    not $open.principal.process.file.full_path = $open.target.process.file.full_path
    // Exclude known legitimate cross-process openers (debuggers, profilers, RMM)
    not $open.principal.process.file.full_path in %linux_allowed_proc_openers
    // Anchor the join on the originating host
    $open.principal.hostname = $hostname

    // Leg 2: Shortly after, an anonymous executable memory region is created
    // on the same host. Chronicle EDR parsers surface this as PROCESS_MODULE_LOAD
    // with a target file path of "[anon]", "memfd:", or "/dev/shm/" indicating
    // a file-less executable mapping — the hallmark of VDSO/GOT patching that
    // loads a malicious shared object without touching disk.
    $anon.metadata.event_type = "PROCESS_MODULE_LOAD"
    // Match anonymous or memfd-backed executable mappings
    $anon.target.process.file.full_path = /(\[anon\]|memfd:|\/dev\/shm\/|\/proc\/[0-9]+\/fd\/)/ nocase
    // Exclude known JIT runtimes that legitimately create anonymous exec regions
    not $anon.principal.process.file.full_path in %linux_allowed_anon_exec_mappers
    $anon.principal.hostname = $hostname

    // Chronological ordering: process open must precede the anonymous exec mapping
    $open.metadata.event_timestamp.seconds <= $anon.metadata.event_timestamp.seconds

  match:
    $hostname over 5m

  outcome:
    $risk_score = max(85)
    $mitre_technique_id = array_distinct("T1055.014")
    $primary_entity = array_distinct($hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $opened_target_process = array_distinct($open.target.process.file.full_path)
    $anon_map_process = array_distinct($anon.principal.process.file.full_path)
    $anon_map_path = array_distinct($anon.target.process.file.full_path)
    $open_event_count = count($open.metadata.id)
    $anon_map_event_count = count($anon.metadata.id)

  condition:
    $open and $anon
}

rule MSSP_T1055_015_ListPlanting_Process_Handle_Request {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a process opening a handle to another process with VM_WRITE and VM_OPERATION access rights, which is a prerequisite for ListPlanting injection. The attacker must write shellcode into the target process memory space before sending the LVM_SORTITEMS message to trigger execution via the SysListView32 callback. This rule pivots on the PROCESS_OPEN telemetry layer rather than command-line arguments, providing additive coverage orthogonal to process-creation rules."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.015"
    mitre_technique_name = "Process Injection: ListPlanting"
    log_prerequisites = "Requires EDR telemetry that records process handle open events with access mask details (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, or Sysmon Event ID 10). The principal.process and target.process fields must be populated with file paths and the target.process.access_mask or equivalent field must be captured."
    platform = "Windows"
    false_positives = "Legitimate debuggers (WinDbg, x64dbg, Visual Studio debugger), process monitoring tools (Process Hacker, Process Explorer), RMM agents performing memory inspection, AV/EDR self-protection reads, and some game anti-cheat engines. Exclude known admin and security tooling paths via reference lists."
    tuning_guidance = "Populate %global_allowed_process_injection_sources with full paths of approved debuggers, RMM agents, and security tools. Populate %global_allowed_injection_targets with paths of processes that legitimately receive cross-process writes (e.g., browser helper processes under vendor management). Narrow scope by also requiring the target process to host a SysListView32 window (e.g., explorer.exe, taskmgr.exe, mmc.exe) if your EDR surfaces window class information."

  events:
    $open.metadata.event_type = "PROCESS_OPEN"

    // Requesting process must not be a known-safe tool
    not $open.principal.process.file.full_path in %global_allowed_process_injection_sources

    // Target process is a GUI application likely to host SysListView32 controls.
    // Common hosts: explorer, taskmgr, mmc, regedit, eventvwr, compmgmt, dfrgui.
    // Regex matches the executable name at the end of any path to avoid hardcoded dirs.
    $open.target.process.file.full_path = /\\(explorer|taskmgr|mmc|regedit|eventvwr|compmgmt|dfrgui|resmon|perfmon|diskmgmt|devmgmt|services|lusrmgr|gpedit|wmimgmt|fsmgmt|certmgr|dsa|dsac|azman|odbcad32|odbcconf|colorcpl|iexplore|msedge|chrome|firefox)\.exe$/ nocase

    // Target must not be an approved injection destination
    not $open.target.process.file.full_path in %global_allowed_injection_targets

    // The requesting process must not be the same binary as the target
    // (self-opens are normal for process introspection)
    // Expressed by requiring the principal path to differ from the target path pattern above:
    // We exclude cases where the opener IS the same well-known GUI host opening itself.
    not $open.principal.process.file.full_path = /\\(explorer|taskmgr|mmc|regedit|eventvwr|compmgmt|dfrgui|resmon|perfmon|diskmgmt|devmgmt|services|lusrmgr|gpedit|wmimgmt|fsmgmt|certmgmt|dsa|dsac|azman|odbcad32|odbcconf|colorcpl)\.exe$/ nocase

    // Opener must not be a Microsoft-signed system process performing routine IPC.
    // Exclude common benign openers by path prefix pattern.
    not $open.principal.process.file.full_path = /\\(svchost|lsass|csrss|wininit|winlogon|smss|services|spoolsv|SearchIndexer|MsMpEng|SgrmBroker|SecurityHealthService)\.exe$/ nocase

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1055.015")
    $primary_entity = array_distinct($open.principal.hostname)
    $opener_process = array_distinct($open.principal.process.file.full_path)
    $target_process = array_distinct($open.target.process.file.full_path)
    $opener_user = array_distinct($open.principal.user.userid)

  condition:
    $open
}

rule MSSP_T1055_015_ListPlanting_WriteMemory_Then_SendMessage {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Sequence"
    severity = "High"
    description = "Detects the ListPlanting injection pattern: a process opens a handle to a remote process (PROCESS_OPEN) followed by a network or inter-process communication event from the same host, indicating code was written into a SysListView32 target and a sort callback was triggered via SendMessage/LVM_SORTITEMS. This is additive coverage over process-launch command-line rules and targets the memory-write + message-dispatch phase of the attack."
    mitre_tactic = "Defense Evasion, Privilege Escalation"
    mitre_technique = "T1055.015"
    mitre_technique_name = "Process Injection: ListPlanting"
    log_prerequisites = "Requires EDR telemetry that emits PROCESS_OPEN events (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint via Chronicle ingestion) and PROCESS_INJECTION or PROCESS_MODULE_LOAD events from the same host."
    platform = "Windows"
    false_positives = "Legitimate accessibility tools (e.g., screen readers, automation frameworks like AutoIt/AutoHotkey, UI testing harnesses) that enumerate and interact with list-view controls in other processes. Remote desktop or session management software. Developer IDEs with live UI inspection features."
    tuning_guidance = "Add known-good parent process paths to %global_allowed_ui_automation_tools. Add known-good target process paths to %global_allowed_listplant_targets. Narrow the PROCESS_OPEN filter to specific high-value target processes if false-positive volume is high."

  events:
    // Leg 1: A process opens a handle to another process - prerequisite for
    // writing shellcode into the target's virtual address space.
    // PROCESS_OPEN is the UDM event type for OpenProcess-style handle acquisition.
    $open.metadata.event_type = "PROCESS_OPEN"
    // The opener must not be a known-good UI automation tool
    not $open.principal.process.file.full_path in %global_allowed_ui_automation_tools
    // Exclude system-level openers that are expected to open handles constantly
    not $open.principal.process.file.full_path = /\\(lsass|csrss|smss|wininit|services)\.exe$/ nocase
    // The target of the open must not be a known-good target
    not $open.target.process.file.full_path in %global_allowed_listplant_targets
    // Exclude self-opens (same process family, e.g. crash reporters)
    $open.principal.process.file.full_path != $open.target.process.file.full_path
    // Bind the joining placeholder
    $open.principal.hostname = $hostname

    // Leg 2: Shortly after the handle acquisition, the same host generates a
    // PROCESS_INJECTION event, indicating code was written into the remote
    // process and execution was triggered (e.g., via LVM_SORTITEMS SendMessage).
    $inj.metadata.event_type = "PROCESS_INJECTION"
    // The injecting process must match the opener from leg 1
    $inj.principal.process.file.full_path = $injector_path
    // Exclude known-good injection sources (e.g., AV, EDR self-protection)
    not $inj.principal.process.file.full_path in %global_allowed_ui_automation_tools
    // The injection target should be a GUI-hosting process (has a message loop)
    // Common hosts for SysListView32: explorer, mmc, taskmgr, regedit, etc.
    $inj.target.process.file.full_path = /\\(explorer|mmc|taskmgr|regedit|control|rundll32|dllhost|svchost)\.exe$/ nocase
    $inj.principal.hostname = $hostname

    // Bind the injector path across both legs so the same process is responsible
    $open.principal.process.file.full_path = $injector_path

    // Enforce chronological ordering: handle open must precede injection
    $open.metadata.event_timestamp.seconds <= $inj.metadata.event_timestamp.seconds

  match:
    $hostname, $injector_path over 5m

  outcome:
    $risk_score = max(85)
    $mitre_technique_id = array_distinct("T1055.015")
    $primary_entity = array_distinct($inj.principal.hostname)
    $injecting_process = array_distinct($inj.principal.process.file.full_path)
    $injected_target_process = array_distinct($inj.target.process.file.full_path)
    $target_process_pid = array_distinct($inj.target.process.pid)
    $open_event_count = count($open.metadata.id)
    $injection_event_count = count($inj.metadata.id)

  condition:
    $open and $inj
}

rule MSSP_T1059_007_JS_Dropper_File_Artifact {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects file creation of JavaScript-based execution artifacts (WSF, HTA, JSE, JXA compiled scripts) in user-writable or temporary directories. Adversaries staging or dropping these files represent a state change that is harder to evade than command-line logging. Covers JScript (Windows), WSH scripts, and JXA compiled artifacts (macOS)."
    mitre_tactic = "Execution"
    mitre_technique = "T1059.007"
    mitre_technique_name = "Command and Scripting Interpreter: JavaScript"
    log_prerequisites = "Requires EDR file telemetry (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, Sysmon Event ID 11). File creation events must include full target path."
    platform = "Linux, macOS, Windows"
    false_positives = "Web development toolchains writing build artifacts, Node.js package managers (npm/yarn) extracting modules, legitimate software installers dropping HTA setup wizards, macOS Automator workflows compiling JXA applets."
    tuning_guidance = "Add known-good parent process paths (e.g., installer engines, IDE processes) to %global_allowed_js_dropper_parents. Add approved staging directories to %global_allowed_js_staging_dirs. Consider raising severity if the creating process is a browser, document reader, or email client."

  events:
    $file.metadata.event_type = "FILE_CREATION"

    // Match JavaScript-family execution artifact extensions
    // Covers: .js (bare), .jse (encoded JScript), .wsf (Windows Script File),
    //         .hta (HTML Application), .scpt (compiled JXA/AppleScript bundle),
    //         .app bundles compiled via osacompile, .wsh (WSH config)
    $file.target.file.full_path = /\.(js|jse|wsf|hta|wsh|scpt)$/i nocase

    // Restrict to high-risk writable locations across all three platforms:
    // Windows: %TEMP%, %APPDATA%, %PUBLIC%, Downloads, user profile root
    // macOS:   /tmp, /var/folders, ~/Library/Application Support, ~/Downloads
    // Linux:   /tmp, /var/tmp, /dev/shm, home subdirs
    $file.target.file.full_path = /(\\Temp\\|\\AppData\\|\\Downloads\\|\\Public\\|\/tmp\/|\/var\/tmp\/|\/var\/folders\/|\/dev\/shm\/|\/Downloads\/|Library\/Application Support\/)/ nocase

    // Exclude known-good parent processes (build tools, package managers, IDEs)
    not $file.principal.process.file.full_path in %global_allowed_js_dropper_parents

    // Exclude known-good staging directories (e.g., approved software depots)
    not $file.target.file.full_path in %global_allowed_js_staging_dirs

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1059.007")
    $primary_entity = array_distinct($file.principal.hostname)
    $dropped_file_path = array_distinct($file.target.file.full_path)
    $creating_process = array_distinct($file.principal.process.file.full_path)
    $creating_user = array_distinct($file.principal.user.userid)

  condition:
    $file
}

rule MSSP_T1071_001_Suspicious_Web_Protocol_Config_Artifact {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects file artifacts written to suspicious locations that are consistent with C2 beacon configuration files, implant staging, or HTTP/WebSocket channel configuration dropped by malware using web protocols. Targets the resulting file-system state change rather than the process command line, providing coverage that survives command-line obfuscation and LOLBin abuse."
    mitre_tactic = "Command and Control"
    mitre_technique = "T1071.001"
    mitre_technique_name = "Application Layer Protocol: Web Protocols"
    log_prerequisites = "Requires EDR file-creation/modification telemetry (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, Sysmon Event ID 11). File path and writing-process fields must be populated."
    platform = "Windows, Linux, macOS"
    false_positives = "Legitimate software update agents writing config files to temp directories; browser extension installers; developer tooling (curl, wget) writing response bodies to disk; RMM agents caching configuration. Tune by adding known-good parent process paths to %global_allowed_web_config_writers."
    tuning_guidance = "Add trusted parent process full paths (e.g., software update agents, RMM tools) to %global_allowed_web_config_writers. Add approved directories to %global_allowed_web_artifact_paths. Raise severity if the writing process is not a browser or update agent."

  events:
    $file.metadata.event_type = "FILE_CREATION"

    // Written to high-risk staging or temp locations across Windows, Linux, macOS
    $file.target.file.full_path = /(?i)(\\temp\\|\\tmp\\|\\appdata\\local\\temp\\|\/tmp\/|\/var\/tmp\/|\/dev\/shm\/|\\programdata\\|\/Library\/Application Support\/|\\users\\[^\\]+\\appdata\\roaming\\)/

    // File extensions associated with C2 config blobs, encoded payloads, or
    // HTTP response bodies cached by implants. Excludes common browser cache
    // extensions to reduce noise.
    $file.target.file.full_path = /\.(dat|bin|cfg|config|ini|json|xml|log|tmp|cache|bak|db|sqlite|raw|enc|b64|out|rsp|hdr|pkt)$/ nocase

    // The writing process is NOT a known browser or update binary.
    // Attackers use LOLBins or renamed binaries; we match on the absence of
    // expected writers rather than an allowlist of attacker tool names.
    not $file.principal.process.file.full_path = /\\(chrome|firefox|msedge|safari|opera|iexplore|brave|vivaldi|MicrosoftEdgeUpdate|GoogleUpdate|MsMpEng|svchost|wuauclt|TiWorker|OneDrive|Dropbox|Teams|slack|zoom)\.exe$/ nocase

    // Exclude known-good parent processes supplied per-customer via reference list
    not $file.principal.process.file.full_path in %global_allowed_web_config_writers

    // Exclude known-good destination paths supplied per-customer via reference list
    not $file.target.file.full_path in %global_allowed_web_artifact_paths

    // The writing process itself is not located in a standard system directory,
    // OR it is a scripting host / LOLBin writing to a user-writable path.
    // This catches renamed implants dropped outside Program Files / System32.
    $file.principal.process.file.full_path = /(?i)(\\users\\|\\temp\\|\\tmp\\|\\programdata\\|\/tmp\/|\/var\/tmp\/|\/dev\/shm\/|\/home\/|\\appdata\\)/

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1071.001")
    $primary_entity = array_distinct($file.principal.hostname)
    $writing_process = array_distinct($file.principal.process.file.full_path)
    $artifact_path = array_distinct($file.target.file.full_path)
    $affected_user = array_distinct($file.principal.user.userid)

  condition:
    $file
}

rule MSSP_T1071_002_FTP_Drop_In_Sensitive_Path {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects file creation events in directories commonly targeted by FTP-based C2 implants and data staging — specifically files written by FTP daemon processes or in FTP root/home paths. Attackers abusing T1071.002 (File Transfer Protocols) frequently drop payloads, scripts, or configuration files via FTP rather than interactive shells, leaving a file artifact even when command-line logging is absent or evaded. This rule targets the resulting file-system state change rather than the FTP client invocation."
    mitre_tactic = "Command and Control"
    mitre_technique = "T1071.002"
    mitre_technique_name = "Application Layer Protocol: File Transfer Protocols"
    log_prerequisites = "Requires EDR file-creation telemetry (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, Sysmon Event ID 11) ingested into Chronicle UDM. The principal.process.file.full_path field must be populated with the writing process path."
    platform = "Linux, Windows, ESXi, macOS"
    false_positives = "Legitimate FTP servers used for software distribution, backup agents writing to FTP roots, managed file transfer (MFT) platforms such as GoAnywhere or MOVEit, web hosting control panels (cPanel, Plesk). Add known-good writer processes to %global_allowed_ftp_writers and known-good paths to %global_allowed_ftp_drop_paths."
    tuning_guidance = "Populate %global_allowed_ftp_writers with full paths of approved MFT/backup agents. Populate %global_allowed_ftp_drop_paths with approved FTP root directories. Raise severity to Critical if the dropped file extension matches executable types (see regex). Consider correlating with subsequent PROCESS_LAUNCH from the same path."

  events:
    $file.metadata.event_type = "FILE_CREATION"

    // Written by an FTP daemon, FTP service, or a process whose name suggests
    // an FTP client/server binary. Covers vsftpd, proftpd, pure-ftpd, ftpd,
    // Windows IIS FTP (svchost hosting ftpsvc), FileZilla Server, and generic
    // ftp binaries. Regex is intentionally broad to survive binary renaming
    // attempts that keep the service wrapper name intact.
    (
      $file.principal.process.file.full_path = /[\/\\](vsftpd|proftpd|pure-ftpd|ftpd|in\.ftpd|xferlog|ftpsvc|filezilla\s*server|ftp)([^\/\\]*)?$/ nocase
      or
      // File dropped into a path that is structurally an FTP root, anonymous
      // share, or common FTP staging directory across Linux, Windows, and ESXi.
      // Covers: /var/ftp, /srv/ftp, /home/ftp, /pub, C:\inetpub\ftproot,
      // C:\FTP, /vmfs/volumes staging, and similar.
      $file.target.file.full_path = /([\/\\](var[\/\\]ftp|srv[\/\\]ftp|home[\/\\]ftp|pub[\/\\]|inetpub[\/\\]ftproot|ftproot|ftp[\/\\]pub|ftp[\/\\]incoming|ftp[\/\\]upload|ftp[\/\\]drop|vmfs[\/\\]volumes[\/\\][^\/\\]+[\/\\]ftp))/ nocase
    )

    // Focus on file types that represent executable payloads, scripts,
    // archives, or configuration drops — the artifacts most relevant to C2.
    $file.target.file.full_path = /\.(exe|elf|sh|bash|py|pl|rb|ps1|bat|cmd|vbs|js|jar|war|php|asp|aspx|so|dylib|ko|tar|gz|zip|7z|rar|bin|run|out|cron|conf|cfg|ini|service|timer)$/ nocase

    // Exclude known-good writer processes (MFT platforms, backup agents, etc.)
    not $file.principal.process.file.full_path in %global_allowed_ftp_writers

    // Exclude known-good FTP root paths approved per environment
    not $file.target.file.full_path in %global_allowed_ftp_drop_paths

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1071.002")
    $primary_entity = array_distinct($file.principal.hostname)
    $dropped_file_path = array_distinct($file.target.file.full_path)
    $writing_process = array_distinct($file.principal.process.file.full_path)

  condition:
    $file
}

rule MSSP_T1071_005_PubSub_Protocol_Config_File_Creation {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "Medium"
    description = "Detects creation or modification of pub/sub protocol client configuration files (MQTT, AMQP, XMPP, STOMP) in non-standard or user-writable directories. Adversaries deploying pub/sub C2 agents typically drop a broker configuration file containing connection strings, credentials, and topic subscriptions. Detecting the artifact is more resilient than command-line matching because the file must exist for the agent to function across reboots."
    mitre_tactic = "Command and Control"
    mitre_technique = "T1071.005"
    mitre_technique_name = "Application Layer Protocol: Publish/Subscribe Protocols"
    log_prerequisites = "Requires EDR file-creation/modification telemetry (e.g., CrowdStrike Falcon, SentinelOne, Microsoft Defender for Endpoint, Sysmon Event ID 11). File path and extension must be populated in target.file.full_path."
    platform = "Windows, Linux, macOS"
    false_positives = "Legitimate IoT development tooling (Mosquitto, RabbitMQ clients, ActiveMQ), CI/CD pipelines writing broker configs, messaging middleware installers, home-automation platforms (Home Assistant), and developer workstations running MQTT explorers."
    tuning_guidance = "Add known-good parent process paths to %global_allowed_pubsub_writers. Add approved directories (e.g., application install paths) to %global_allowed_pubsub_dirs. Raise severity if the writing process is an interpreter (python, node, powershell) rather than a dedicated messaging binary."

  events:
    $file.metadata.event_type = "FILE_CREATION"

    // Target file path matches pub/sub configuration file naming conventions
    // Covers MQTT (.conf, .cfg, .ini, .json, .yaml, .yml, .toml),
    // AMQP/RabbitMQ, XMPP, and STOMP client config patterns
    $file.target.file.full_path = /\/(mqtt|amqp|amqps|xmpp|stomp|rabbitmq|mosquitto|activemq|paho|emqx|hivemq|nats)[^\/]*\.(conf|cfg|ini|json|yaml|yml|toml|xml|properties)$/  nocase

    // OR: generic config files whose names embed broker/topic keywords
    // Second filter broadens to files in temp/user-writable paths with broker keywords
    // We use OR-equivalent by splitting into two separate conditions joined with OR logic
    // YARA-L does not support OR across conditions, so we use a broad path regex
    // and rely on the filename pattern above as the primary signal

    // Restrict to directories that are suspicious for this file type:
    // temp dirs, user home dirs, working dirs, hidden dirs, /tmp, AppData, /var/tmp
    $file.target.file.full_path = /(\/tmp\/|\/var\/tmp\/|\/dev\/shm\/|\\Temp\\|\\AppData\\|\\ProgramData\\|\/home\/[^\/]+\/\.|\\Users\\[^\\]+\\AppData|\/root\/\.|\/opt\/[^\/]+\/conf)/ nocase

    // Exclude known-good writer processes (messaging middleware installers, package managers)
    not $file.principal.process.file.full_path in %global_allowed_pubsub_writers

    // Exclude known-good directories where legitimate broker software installs configs
    not $file.target.file.full_path in %global_allowed_pubsub_dirs

    // Exclude system-level package manager paths to reduce installer noise
    not $file.principal.process.file.full_path = /\/(usr\/bin\/apt|usr\/bin\/yum|usr\/bin\/dnf|usr\/bin\/rpm|usr\/bin\/dpkg|usr\/sbin\/installer|Windows\/System32\/msiexec)/ nocase

  outcome:
    $risk_score = max(55)
    $mitre_technique_id = array_distinct("T1071.005")
    $primary_entity = array_distinct($file.principal.hostname)
    $writing_process = array_distinct($file.principal.process.file.full_path)
    $config_file_path = array_distinct($file.target.file.full_path)
    $writing_user = array_distinct($file.principal.user.userid)

  condition:
    $file
}

rule MSSP_T1555_005_Password_Manager_DB_Suspicious_Read {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects a non-password-manager process opening a password manager database file for read access. Adversaries extract credentials by reading the encrypted database from disk using a separate process (e.g., a shell, scripting engine, or custom tool), bypassing the legitimate application entirely. This rule fires on the FILE_READ event produced when an unexpected process accesses well-known password manager database file paths or extensions."
    mitre_tactic = "Credential Access"
    mitre_technique = "T1555.005"
    mitre_technique_name = "Credentials from Password Stores: Password Managers"
    log_prerequisites = "Requires EDR file-read telemetry (e.g., CrowdStrike Falcon, Microsoft Defender for Endpoint, SentinelOne, or Sysmon Event ID 11/15 with file-read auditing enabled). The EDR must populate principal.process.file.full_path and target.file.full_path on FILE_READ events."
    platform = "Linux, macOS, Windows"
    false_positives = "Backup agents (e.g., Veeam, Acronis, Time Machine) reading the entire user profile; antivirus scanners performing on-access scanning; cloud sync clients (Dropbox, OneDrive, iCloud) syncing the vault file; the legitimate password manager application itself performing self-backup or auto-save."
    tuning_guidance = "Add legitimate backup and sync process paths to %pm_db_allowed_readers. Add site-specific password manager executable paths to %pm_legitimate_executables so they are excluded. If cloud sync generates high volume, also add the sync agent path to %pm_db_allowed_readers."

  events:
    $file.metadata.event_type = "FILE_READ"

    // Target: well-known password manager database file extensions and names
    // Covers KeePass (.kdbx, .kdb), 1Password (.agilekeychain, .opvault, .1pif),
    // LastPass (lastpass_form_fills.db, lpdb), Bitwarden (data.json vault export),
    // Dashlane (.dash, .aesdb), RoboForm (.rfo, .rfp), Enpass (.enpassdb),
    // macOS Keychain (.keychain, .keychain-db), generic password store patterns
    $file.target.file.full_path = /\.(kdbx|kdb|agilekeychain|opvault|1pif|dash|aesdb|rfo|rfp|enpassdb|keychain|keychain\-db|lpdb|psafe3|pwm|bwdb)$/ nocase

    // Also catch common named vault files that lack a distinctive extension
    // (e.g., Bitwarden data.json, LastPass form fills sqlite db)
    // Combined OR via a second regex on the filename component
    // Note: Chronicle evaluates multiple predicates on the same field as AND;
    // we use a broad path regex that matches the directory patterns instead.
    // Primary coverage is the extension match above; the process exclusion below
    // provides the behavioral signal.

    // Exclude the legitimate password manager processes themselves performing reads
    not $file.principal.process.file.full_path = /\/(KeePass|KeePassXC|1Password|LastPass|Bitwarden|Dashlane|RoboForm|Enpass|keepassxc|keepass)/ nocase
    not $file.principal.process.file.full_path = /\\(KeePass|KeePassXC|1Password|LastPass|Bitwarden|Dashlane|RoboForm|Enpass|keepass)/ nocase

    // Exclude known-good backup, sync, and AV processes via reference list
    not $file.principal.process.file.full_path in %pm_db_allowed_readers

    // Exclude the password manager's own helper/updater processes
    not $file.principal.process.file.full_path in %pm_legitimate_executables

    // Require a principal process to be present (filter out kernel/system reads
    // that may appear with empty process paths)
    $file.principal.process.file.full_path != ""

  outcome:
    $risk_score = max(80)
    $mitre_technique_id = array_distinct("T1555.005")
    $primary_entity = array_distinct($file.principal.hostname)
    $accessing_process = array_distinct($file.principal.process.file.full_path)
    $accessed_vault_file = array_distinct($file.target.file.full_path)
    $user_context = array_distinct($file.principal.user.userid)

  condition:
    $file
}

rule MSSP_T1555_006_Cloud_Secret_Bulk_Read_API {
  meta:
    author = "TELUS Automated Detection Pipeline"
    rule_type = "Single-Event"
    severity = "High"
    description = "Detects USER_RESOURCE_ACCESS events representing direct API reads of secrets from cloud-native secret management stores (AWS Secrets Manager, GCP Secret Manager, Azure Key Vault). This rule targets the resulting cloud audit log entry produced when a secret value is retrieved, providing coverage at the API/audit layer rather than the process-creation layer. Bulk or anomalous secret reads by non-service identities are a strong indicator of credential harvesting."
    mitre_tactic = "Credential Access"
    mitre_technique = "T1555.006"
    mitre_technique_name = "Credentials from Password Stores: Cloud Secrets Management Stores"
    log_prerequisites = "Requires cloud audit logs ingested into Chronicle UDM: AWS CloudTrail (GetSecretValue), GCP Cloud Audit Logs (AccessSecretVersion), Azure Monitor / Key Vault diagnostic logs (SecretGet). These must be forwarded to Google SecOps via the appropriate Chronicle ingestion feeds."
    platform = "IaaS (AWS, GCP, Azure)"
    false_positives = "Legitimate application service accounts performing scheduled secret rotation checks, CI/CD pipeline identities fetching deployment credentials, secrets manager SDK health checks, authorized break-glass access by SRE teams."
    tuning_guidance = "Populate %cloud_secret_allowed_service_accounts with known CI/CD and application service account identities. Populate %cloud_secret_allowed_resource_prefixes with approved automation resource name patterns. Consider raising severity or lowering threshold for human (non-service) identities accessing secrets outside business hours."

  events:
    $cloud.metadata.event_type = "USER_RESOURCE_ACCESS"

    // Match the canonical secret-read API actions across AWS, GCP, and Azure
    // as they appear in Chronicle UDM after normalization from cloud audit logs.
    // AWS CloudTrail: GetSecretValue
    // GCP Cloud Audit: google.cloud.secretmanager.v1.SecretManagerService.AccessSecretVersion
    // Azure Key Vault: SecretGet / VaultGet
    $cloud.metadata.product_event_type = /GetSecretValue|AccessSecretVersion|SecretGet|VaultGet/ nocase

    // Target resource must reference a secrets management service path or ARN pattern.
    // AWS: arn:aws:secretsmanager:...
    // GCP: projects/.../secrets/.../versions/...
    // Azure: https://<vault>.vault.azure.net/secrets/...
    $cloud.target.resource.name = /secretsmanager|secretmanager|vault\.azure\.net\/secrets|\/secrets\/.*\/versions\// nocase

    // Capture the principal identity performing the access
    $cloud.principal.user.userid = $accessor

    // Exclude known-good automation service accounts
    not $cloud.principal.user.userid in %cloud_secret_allowed_service_accounts

    // Exclude known-good resource name prefixes (e.g. approved rotation automation targets)
    not $cloud.target.resource.name in %cloud_secret_allowed_resource_prefixes

  outcome:
    $risk_score = max(72)
    $mitre_technique_id = array_distinct("T1555.006")
    $primary_entity = array_distinct($cloud.principal.user.userid)
    $accessed_secret_resource = array_distinct($cloud.target.resource.name)
    $cloud_api_action = array_distinct($cloud.metadata.product_event_type)
    $source_ip = array_distinct($cloud.principal.ip)

  condition:
    $cloud
}

rule TELUS_T1685_001_Disable_or_Modify_Windows_Event_Log {
  meta:
    author = "TELUS Security Operations"
    description = "Detects attempts to disable or modify the Windows Event Log service or audit policy via command-line tools, PowerShell, registry modification, or service control commands. Covers T1685.001 - Disable or Modify Windows Event Log."
    mitre_attack_technique = "T1685.001 - Disable or Modify Windows Event Log"
    mitre_attack_tactic = "Defense Impairment"
    severity = "HIGH"
    false_positive = "Legitimate system administrators may disable or reconfigure the EventLog service during maintenance windows or audit policy changes. Verify with change management records. Security tooling and endpoint management platforms may also invoke auditpol.exe or sc.exe legitimately."
    platform = "Windows"
    version = "1.0"
    created = "2025-01-01"

  events:
    (
      // Detect PowerShell commands to stop or disable the EventLog service
      $e1.metadata.event_type = "PROCESS_LAUNCH" and
      (
        (
          re.regex($e1.target.process.file.full_path, `(?i)(powershell\.exe|pwsh\.exe)$`) and
          (
            re.regex($e1.principal.process.command_line, `(?i)Set-Service\s+.*EventLog.*(-Status\s+Stopped|-StartupType\s+Disabled)`) or
            re.regex($e1.principal.process.command_line, `(?i)Stop-Service\s+.*EventLog`) or
            re.regex($e1.principal.process.command_line, `(?i)Set-Service\s+.*-Name\s+EventLog`) or
            re.regex($e1.target.process.command_line, `(?i)Set-Service\s+.*EventLog.*(-Status\s+Stopped|-StartupType\s+Disabled)`) or
            re.regex($e1.target.process.command_line, `(?i)Stop-Service\s+.*EventLog`) or
            re.regex($e1.target.process.command_line, `(?i)Set-Service\s+.*-Name\s+EventLog`)
          )
        ) or
        // Detect sc.exe disabling the EventLog service
        (
          re.regex($e1.target.process.file.full_path, `(?i)(\\sc\.exe)$`) and
          (
            re.regex($e1.target.process.command_line, `(?i)sc\s+(config|stop)\s+eventlog`) or
            re.regex($e1.principal.process.command_line, `(?i)sc\s+(config|stop)\s+eventlog`)
          )
        ) or
        // Detect net.exe stopping the EventLog service
        (
          re.regex($e1.target.process.file.full_path, `(?i)(\\net\.exe|\\net1\.exe)$`) and
          (
            re.regex($e1.target.process.command_line, `(?i)net\s+stop\s+eventlog`) or
            re.regex($e1.principal.process.command_line, `(?i)net\s+stop\s+eventlog`)
          )
        ) or
        // Detect auditpol.exe clearing or disabling audit policies
        (
          re.regex($e1.target.process.file.full_path, `(?i)(\\auditpol\.exe)$`) and
          (
            re.regex($e1.target.process.command_line, `(?i)auditpol\s+.*(\/clear|\/remove|\/set.*disable|\/set.*no auditing)`) or
            re.regex($e1.principal.process.command_line, `(?i)auditpol\s+.*(\/clear|\/remove|\/set.*disable|\/set.*no auditing)`)
          )
        ) or
        // Detect wevtutil.exe clearing or disabling event logs
        (
          re.regex($e1.target.process.file.full_path, `(?i)(\\wevtutil\.exe)$`) and
          (
            re.regex($e1.target.process.command_line, `(?i)wevtutil\s+(cl|clear-log|sl|set-log)\s+`) or
            re.regex($e1.principal.process.command_line, `(?i)wevtutil\s+(cl|clear-log|sl|set-log)\s+`)
          )
        )
      )
    ) or
    // Detect registry modification to disable EventLog service startup
    (
      $e1.metadata.event_type = "REGISTRY_MODIFICATION" and
      re.regex($e1.target.registry.registry_key, `(?i)HKEY_LOCAL_MACHINE\\SYSTEM\\(CurrentControlSet|ControlSet\d+)\\Services\\EventLog`) and
      re.regex($e1.target.registry.registry_key, `(?i)\\Start$`)
    )

  condition:
    $e1
}

rule TELUS_T1685_002_Disable_or_Modify_Cloud_Log {

  meta:
    author = "TELUS Detection Engineering"
    description = "Detects attempts to disable or modify cloud logging capabilities including AWS CloudTrail/CloudWatch, Azure Monitor, GCP logging, and Office 365 audit logging. Adversaries with sufficient permissions may tamper with logging to evade detection of subsequent malicious activity."
    mitre_attack_technique = "T1685.002 - Disable or Modify Cloud Log"
    mitre_attack_tactic = "Defense Impairment"
    severity = "HIGH"
    false_positive = "Legitimate cloud administrators performing authorized maintenance, log rotation, or infrastructure changes. Security teams conducting authorized audits or configuration changes. Automated infrastructure-as-code pipelines (Terraform, CloudFormation) performing planned changes. Validate against change management records."
    platform = "IaaS, SaaS, Identity Provider, Office Suite"
    reference = "https://attack.mitre.org/techniques/T1685/002/"
    rule_version = "1.0"
    created = "2025-01-01"

  events:

    // Pattern 1: Process-based detection for CLI tools disabling cloud logging
    $proc_event.metadata.event_type = "PROCESS_LAUNCH"
    (
      // AWS CloudTrail disable/modify operations via CLI
      re.regex($proc_event.principal.process.command_line, `(?i)(aws\s+cloudtrail\s+(delete-trail|stop-logging|update-trail|remove-tags|put-event-selectors))`) nocase or
      // AWS CloudWatch log group deletion or retention modification
      re.regex($proc_event.principal.process.command_line, `(?i)(aws\s+logs\s+(delete-log-group|delete-log-stream|delete-retention-policy|delete-subscription-filter|disassociate-kms-key))`) nocase or
      // AWS SNS topic removal (associated with CloudTrail notifications)
      re.regex($proc_event.principal.process.command_line, `(?i)(aws\s+sns\s+delete-topic)`) nocase or
      // Azure Monitor / Diagnostic Settings disable
      re.regex($proc_event.principal.process.command_line, `(?i)(az\s+(monitor\s+(diagnostic-settings\s+delete|log-profiles\s+delete|activity-log\s+alert\s+delete)|security\s+audit-policy\s+update))`) nocase or
      // GCP logging disable
      re.regex($proc_event.principal.process.command_line, `(?i)(gcloud\s+(logging\s+(sinks\s+delete|buckets\s+delete|views\s+delete)|projects\s+update.*--no-enable-cloud-logging))`) nocase or
      // Office 365 / Exchange Online audit bypass
      re.regex($proc_event.principal.process.command_line, `(?i)(Set-MailboxAuditBypassAssociation|Set-AdminAuditLogConfig.*-UnifiedAuditLogIngestionEnabled\s+\$?false|Disable-OrganizationCustomization)`) nocase or
      // Pacu or similar cloud attack framework modules
      re.regex($proc_event.principal.process.command_line, `(?i)(pacu.*detection|cloudtrail.*disable|logging.*tamper)`) nocase or
      // Generic patterns for disabling multi-region or log validation
      re.regex($proc_event.principal.process.command_line, `(?i)(--no-enable-log-file-validation|--no-is-multi-region-trail|--no-include-global-service-events)`) nocase or
      // Terraform or infrastructure destroy targeting logging resources
      re.regex($proc_event.principal.process.command_line, `(?i)(terraform\s+(destroy|apply).*cloudtrail|terraform\s+(destroy|apply).*log_group)`) nocase
    )

  condition:
    $proc_event

}

rule MSSP_T1685_003_SecurityUI_Spoof_Burst {
  meta:
    author          = "TELUS Automated Detection Pipeline"
    rule_type       = "Threshold"
    severity        = "High"
    description     = "Detects a burst of process launches within a short window where processes impersonate or reference security-tool UI components (system tray icons, notification windows, health dashboards) from an unusual parent or working path. A single such launch may be benign; repeated launches from the same host in 10 minutes suggest an adversary cycling fake security-tool UI processes to maintain the appearance of protection after disabling the real agent."
    mitre_tactic    = "Defense Evasion"
    mitre_technique = "T1685.003"
    mitre_technique_name = "Modify or Spoof Tool UI"
    log_prerequisites = "Requires EDR process-launch telemetry (e.g., CrowdStrike, SentinelOne, Microsoft Defender for Endpoint, Sysmon Event ID 1) forwarded to Chronicle as PROCESS_LAUNCH UDM events with command_line and parent process path populated."
    platform        = "Windows, Linux, macOS"
    false_positives = "Security product auto-updaters that restart their tray agent repeatedly; software deployment tools (SCCM, Intune) pushing AV updates; RMM agents restarting endpoint protection components; developer workstations running UI test harnesses for security products."
    tuning_guidance = "Add known-good parent process paths (e.g., your RMM agent, software deployment tool) to %global_allowed_security_ui_parents. Raise the threshold count if your environment legitimately restarts security tray agents frequently. Lower severity for hosts in %global_dev_workstations."

  events:
    $proc.metadata.event_type = "PROCESS_LAUNCH"

    // Match processes whose command line or binary path references common
    // security-tool UI surface keywords: tray icons, notification agents,
    // health/status dashboards, or explicit "SecurityHealth" components.
    // Using broad regex so renamed wrappers that still carry the UI keyword
    // in their arguments are caught.
    (
      $proc.target.process.command_line = /security.*health/        nocase or
      $proc.target.process.command_line = /securitycenter/          nocase or
      $proc.target.process.command_line = /defender.*tray/          nocase or
      $proc.target.process.command_line = /av.*notify/              nocase or
      $proc.target.process.command_line = /antivirus.*status/       nocase or
      $proc.target.process.command_line = /endpoint.*protection.*ui/ nocase or
      $proc.target.process.command_line = /edr.*agent.*ui/          nocase or
      $proc.target.process.command_line = /systray.*security/       nocase or
      $proc.target.process.file.full_path = /SecurityHealth/        nocase or
      $proc.target.process.file.full_path = /SecurityCenter/        nocase or
      $proc.target.process.file.full_path = /DefenderTray/          nocase or
      $proc.target.process.file.full_path = /AVNotify/              nocase or
      $proc.target.process.file.full_path = /EPProtectionUI/        nocase
    )

    // Exclude launches whose parent is a known-legitimate security product
    // installation directory or an approved admin tool.
    not $proc.principal.process.file.full_path in %global_allowed_security_ui_parents

    // Exclude processes launched from canonical Windows security directories;
    // a spoofed UI is unlikely to live in the real product path.
    not $proc.target.process.file.full_path = /\\Windows Defender\\/  nocase
    not $proc.target.process.file.full_path = /\\Microsoft Security Client\\/ nocase

    $proc.principal.hostname = $hostname

  match:
    $hostname over 10m

  outcome:
    // Scale risk with volume: base 45, capped at 90.
    // count() returns the number of matching events in the window.
    $risk_score = max(
      if(count($proc.metadata.event_type) >= 15, 90,
      if(count($proc.metadata.event_type) >= 10, 75,
      if(count($proc.metadata.event_type) >= 5,  60,
         45)))
    )
    $mitre_technique_id = array_distinct("T1685.003")
    $primary_entity     = array_distinct($proc.principal.hostname)
    $triggering_user    = array_distinct($proc.principal.user.userid)
    $spawned_binaries   = array_distinct($proc.target.process.file.full_path)
    $parent_processes   = array_distinct($proc.principal.process.file.full_path)
    $event_count        = count($proc.metadata.event_type)

  condition:
    // Conservative threshold: 5 matching launches in 10 minutes from one host.
    #proc >= 5
}

rule TELUS_T1685_004_Disable_or_Modify_Linux_Audit_System_Log {

  meta:
    author = "TELUS Detection Engineering"
    description = "Detects attempts to disable or modify the Linux Audit system (auditd) including stopping the service, killing the daemon, modifying audit rules/config files, or using auditctl to disable logging. Indicative of T1685.004 Defense Impairment activity."
    mitre_attack_technique = "T1685.004 - Disable or Modify Linux Audit System Log"
    mitre_attack_tactic = "Defense Impairment"
    severity = "HIGH"
    false_positive = "Legitimate system administrators performing authorized audit configuration changes, automated configuration management tools (Ansible, Puppet, Chef) modifying audit rules, OS patching processes that restart auditd, and security hardening scripts that reconfigure audit rules."
    platform = "Linux"
    rule_version = "1.0"
    created = "2025-01-01"

  events:

    // Pattern 1: Stopping or disabling auditd via systemctl or service command
    (
      $e1.metadata.event_type = "PROCESS_LAUNCH" and
      (
        (
          re:match($e1.principal.process.command_line, `systemctl\s+(stop|disable|mask|kill)\s+audit`, nocase) or
          re:match($e1.principal.process.command_line, `service\s+auditd?\s+(stop|disable|kill)`, nocase)
        ) or
        // Pattern 2: Killing auditd process directly
        (
          re:match($e1.principal.process.command_line, `kill\s+.*auditd`, nocase) or
          re:match($e1.principal.process.command_line, `killall\s+.*auditd`, nocase) or
          re:match($e1.principal.process.command_line, `pkill\s+.*auditd`, nocase)
        ) or
        // Pattern 3: auditctl used to disable logging or remove all rules
        (
          re:match($e1.principal.process.command_line, `auditctl\s+.*-e\s+0`, nocase) or
          re:match($e1.principal.process.command_line, `auditctl\s+.*-D`, nocase) or
          re:match($e1.principal.process.command_line, `auditctl\s+.*--backlog-limit\s+0`, nocase) or
          re:match($e1.principal.process.command_line, `auditctl\s+.*-b\s+0`, nocase)
        ) or
        // Pattern 4: Overwriting or truncating audit rules/config files via shell redirection
        (
          re:match($e1.principal.process.command_line, `>\s*/etc/audit/audit\.rules`, nocase) or
          re:match($e1.principal.process.command_line, `>\s*/etc/audit/auditd\.conf`, nocase) or
          re:match($e1.principal.process.command_line, `>\s*/etc/audit/rules\.d/`, nocase) or
          re:match($e1.principal.process.command_line, `truncate\s+.*(/etc/audit/audit\.rules|/etc/audit/auditd\.conf)`, nocase) or
          re:match($e1.principal.process.command_line, `shred\s+.*(/etc/audit/audit\.rules|/etc/audit/auditd\.conf)`, nocase)
        ) or
        // Pattern 5: Using sed/awk/perl to modify audit config files inline
        (
          re:match($e1.principal.process.command_line, `(sed|awk|perl)\s+.*-i.*(/etc/audit/audit\.rules|/etc/audit/auditd\.conf|/etc/audit/rules\.d/)`, nocase)
        ) or
        // Pattern 6: Removing audit rules files
        (
          re:match($e1.principal.process.command_line, `rm\s+.*(/etc/audit/audit\.rules|/etc/audit/auditd\.conf|/etc/audit/rules\.d/)`, nocase)
        ) or
        // Pattern 7: chmod/chattr to lock out audit config or logs
        (
          re:match($e1.principal.process.command_line, `chattr\s+.*\+i\s+.*/etc/audit/`, nocase) or
          re:match($e1.principal.process.command_line, `chmod\s+.*000\s+.*/etc/audit/`, nocase) or
          re:match($e1.principal.process.command_line, `chmod\s+.*000\s+.*/var/log/audit/`, nocase)
        )
      )
    )

    or

    // Pattern 8: Direct file modification of audit rules or configuration
    (
      $e1.metadata.event_type = "FILE_CREATION" and
      (
        re:match($e1.target.file.full_path, `/etc/audit/audit\.rules`, nocase) or
        re:match($e1.target.file.full_path, `/etc/audit/auditd\.conf`, nocase) or
        re:match($e1.target.file.full_path, `/etc/audit/rules\.d/.*\.rules`, nocase)
      )
    )

  condition:
    $e1

}

rule TELUS_T1685_006_Clear_Linux_or_Mac_System_Logs {

  meta:
    author = "TELUS Detection Engineering"
    description = "Detects attempts to clear or truncate Linux/macOS system logs under /var/log/ via process execution, file truncation, or deletion commands. Adversaries clear logs to hide evidence of intrusion activity."
    mitre_attack_technique = "T1685.006 - Clear Linux or Mac System Logs"
    mitre_attack_tactic = "Defense Impairment"
    severity = "HIGH"
    platforms = "Linux, macOS"
    false_positive = "Legitimate log rotation tools (logrotate, newsyslog), system administrators performing manual log maintenance, or backup/archival scripts may trigger this rule. Validate against scheduled maintenance windows and authorized admin activity."
    version = "1.0"
    created = "2024-01-01"

  events:

    // Event 1: Process-based log clearing via shell commands (truncate, shred, rm, cat /dev/null)
    $proc_clear.metadata.event_type = "PROCESS_LAUNCH"
    (
      // Truncate command targeting /var/log
      re.regex($proc_clear.principal.process.command_line, `truncate\s+.*(-s\s*0|--size[=\s]+0).*\/var\/log\/`) nocase or
      re.regex($proc_clear.principal.process.command_line, `truncate\s+.*\/var\/log\/.*(-s\s*0|--size[=\s]+0)`) nocase or

      // cat /dev/null redirect to log file
      re.regex($proc_clear.principal.process.command_line, `cat\s+\/dev\/null\s*>\s*\/var\/log\/`) nocase or
      re.regex($proc_clear.principal.process.command_line, `>\s*\/var\/log\/[^\s]+\.(log|txt|1|0|gz)?`) nocase or

      // echo empty string redirect to log file
      re.regex($proc_clear.principal.process.command_line, `echo\s+['"]{2}\s*>\s*\/var\/log\/`) nocase or
      re.regex($proc_clear.principal.process.command_line, `echo\s+-n\s+['"]{0,2}\s*>\s*\/var\/log\/`) nocase or

      // shred targeting /var/log
      re.regex($proc_clear.principal.process.command_line, `shred\s+.*(\/var\/log\/)`) nocase or

      // rm targeting specific log files under /var/log
      re.regex($proc_clear.principal.process.command_line, `rm\s+(-[rfv]+\s+)?(\/var\/log\/(messages|secure|auth\.log|syslog|kern\.log|cron\.log|maillog|wtmp|utmp|btmp|lastlog|httpd|nginx|apache2|audit\/audit\.log))`) nocase or

      // dd to zero out log files
      re.regex($proc_clear.principal.process.command_line, `dd\s+.*if=\/dev\/(zero|null).*of=\/var\/log\/`) nocase or

      // Python/Perl one-liners to clear log files
      re.regex($proc_clear.principal.process.command_line, `(python[23]?|perl)\s+.*open\s*\(.*\/var\/log\/.*['"]\s*,\s*['"]w['"]`) nocase or

      // install command to zero out log (install -m with /dev/null)
      re.regex($proc_clear.principal.process.command_line, `install\s+.*\/dev\/null\s+\/var\/log\/`) nocase or

      // tee with /dev/null to clear
      re.regex($proc_clear.principal.process.command_line, `tee\s+\/var\/log\/[^\s]+\s*<\s*\/dev\/null`) nocase or

      // macOS specific: log erase or syslog -k
      re.regex($proc_clear.principal.process.command_line, `log\s+erase\s+(--all|--predicate)`) nocase or
      re.regex($proc_clear.principal.process.command_line, `syslog\s+.*-k\s+.*Time\s+ge`) nocase or

      // journalctl vacuum (systemd journal clearing)
      re.regex($proc_clear.principal.process.command_line, `journalctl\s+.*(--rotate|--vacuum-time|--vacuum-size|--flush)`) nocase or
      re.regex($proc_clear.principal.process.command_line, `journalctl\s+.*-m\s*0`) nocase or

      // auditd log clearing
      re.regex($proc_clear.principal.process.command_line, `(aureport|auditctl|ausearch)\s+.*--reset`) nocase or

      // Direct wipe of audit log
      re.regex($proc_clear.principal.process.command_line, `>\s*\/var\/log\/audit\/audit\.log`) nocase
    )

  condition:
    $proc_clear

}

rule TELUS_T1686_Disable_or_Modify_System_Firewall {

  meta:
    author = "TELUS Detection Engineering"
    description = "Detects attempts to disable or modify host-based firewalls across Windows, Linux, macOS, and ESXi platforms. Covers netsh, ufw, iptables, firewall-cmd, pfctl, esxcli, and PowerShell-based firewall manipulation."
    mitre_attack_technique = "T1686 - Disable or Modify System Firewall"
    mitre_attack_tactic = "Defense Impairment"
    severity = "HIGH"
    false_positive = "Legitimate system administrators performing authorized firewall configuration changes, automated configuration management tools (Ansible, Chef, Puppet), and security software installations may trigger this rule. Validate against change management records."
    version = "1.0"
    created = "2025-01-01"
    platform = "Windows, Linux, macOS, ESXi"

  events:
    $e.metadata.event_type = "PROCESS_LAUNCH"

    (
      // Windows - netsh firewall/advfirewall disable or rule modification
      (
        re.regex($e.principal.process.command_line, `netsh\s+(advfirewall|firewall)`, nocase) and
        re.regex($e.principal.process.command_line, `(set\s+(allprofiles|domainprofile|privateprofile|publicprofile|currentprofile|opmode|state|firewallpolicy|rule)|add\s+rule|delete\s+rule)`, nocase) and
        re.regex($e.principal.process.command_line, `(disable|off|allow|bypass)`, nocase)
      )
      or
      // Windows - PowerShell firewall cmdlets
      (
        re.regex($e.principal.process.command_line, `(Set-NetFirewallProfile|Disable-NetFirewallRule|New-NetFirewallRule|Remove-NetFirewallRule|Set-NetFirewallRule)`, nocase) and
        re.regex($e.principal.process.command_line, `(Enabled\s*\$false|-Enabled\s+False|-Action\s+Allow|-Profile\s+(Any|All|Domain|Private|Public))`, nocase)
      )
      or
      // Windows - sc stop/disable Windows Firewall service
      (
        re.regex($e.principal.process.command_line, `(sc\.exe|sc)\s+(stop|config|delete)\s+(mpssvc|mpsdrv|sharedaccess|bfe)`, nocase)
      )
      or
      // Linux - ufw disable or allow
      (
        re.regex($e.principal.process.command_line, `ufw\s+(disable|reset|allow|delete|deny|reject|insert)`, nocase)
      )
      or
      // Linux - iptables flush or permissive policy
      (
        re.regex($e.principal.process.command_line, `iptables\s+`, nocase) and
        re.regex($e.principal.process.command_line, `(-F|-X|-P\s+(INPUT|OUTPUT|FORWARD)\s+ACCEPT|--flush|--delete-chain|--policy\s+(INPUT|OUTPUT|FORWARD)\s+ACCEPT)`, nocase)
      )
      or
      // Linux - firewalld disable or zone manipulation
      (
        re.regex($e.principal.process.command_line, `(firewall-cmd|systemctl)\s+`, nocase) and
        re.regex($e.principal.process.command_line, `(--add-port|--add-service|--remove-service|--zone=drop|--set-default-zone|stop\s+firewalld|disable\s+firewalld)`, nocase)
      )
      or
      // macOS - pfctl disable or flush
      (
        re.regex($e.principal.process.command_line, `pfctl\s+`, nocase) and
        re.regex($e.principal.process.command_line, `(-d|-F\s+(all|rules|nat|queue|state|info|Tables|osfp)|-f\s+/dev/null)`, nocase)
      )
      or
      // macOS - socketfilterfw disable
      (
        re.regex($e.principal.process.command_line, `socketfilterfw\s+`, nocase) and
        re.regex($e.principal.process.command_line, `(--setglobalstate\s+off|--setblockall\s+off|--setstealthmode\s+off|--remove)`, nocase)
      )
      or
      // ESXi - esxcli firewall manipulation
      (
        re.regex($e.principal.process.command_line, `esxcli\s+network\s+firewall`, nocase) and
        re.regex($e.principal.process.command_line, `(set\s+--enabled\s+(false|0)|ruleset\s+set\s+--allowed-all\s+true|ruleset\s+set\s+--enabled\s+false|unload)`, nocase)
      )
      or
      // ESXi - vim-cmd or direct config modification for firewall
      (
        re.regex($e.principal.process.command_line, `(vim-cmd\s+hostsvc/firewall|esxcfg-firewall)`, nocase) and
        re.regex($e.principal.process.command_line, `(-d|--disable|--allowIncoming|--allowOutgoing|--openPort)`, nocase)
      )
      or
      // Network devices - common CLI patterns for disabling firewall/ACL
      (
        re.regex($e.principal.process.command_line, `(no\s+ip\s+(access-list|inspect|firewall)|no\s+firewall|set\s+security-policy\s+disable)`, nocase)
      )
    )

  condition:
    $e
}

rule TELUS_T1686_001_Cloud_Firewall {

  meta:
    author = "TELUS Detection Engineering"
    description = "Detects adversarial modification or disabling of cloud firewall rules, security groups, or network ACLs that may allow unrestricted or overly permissive inbound/outbound access to cloud-hosted resources. Covers creation of permissive ingress rules, deletion of existing firewall rules, and modification of security group policies in IaaS environments."
    mitre_attack_technique = "T1686.001 - Cloud Firewall"
    mitre_attack_tactic = "Defense Impairment"
    severity = "HIGH"
    false_positive = "Legitimate cloud infrastructure automation (Terraform, CloudFormation, Ansible), authorized security group changes by cloud admins, CI/CD pipeline deployments modifying firewall rules. Tune by excluding known automation service accounts and approved change windows."
    platform = "IaaS"
    reference = "https://attack.mitre.org/techniques/T1686/001/"
    rule_version = "1.0"

  events:

    // Event 1: Detect cloud API calls that create, modify, or delete firewall/security group rules
    $api_call.metadata.event_type = "USER_RESOURCE_UPDATE_CONTENT"
    (
      // AWS security group ingress/egress rule modifications
      re.regex($api_call.target.resource.name, `(?i)(AuthorizeSecurityGroupIngress|AuthorizeSecurityGroupEgress|RevokeSecurityGroupIngress|RevokeSecurityGroupEgress|CreateSecurityGroup|DeleteSecurityGroup|ModifySecurityGroupRules)`) or
      // GCP firewall rule modifications
      re.regex($api_call.target.resource.name, `(?i)(firewalls\.insert|firewalls\.patch|firewalls\.delete|firewalls\.update|networks\.updatePolicy)`) or
      // Azure NSG / firewall modifications
      re.regex($api_call.target.resource.name, `(?i)(networkSecurityGroups|securityRules|azureFirewalls|firewallPolicies)`) or
      // Generic cloud firewall keywords
      re.regex($api_call.target.resource.name, `(?i)(firewall.rule|security.group|network.acl|inbound.rule|outbound.rule)`)
    )

    // Event 2: Detect process-level CLI commands used to modify cloud firewall rules
    $proc.metadata.event_type = "PROCESS_LAUNCH"
    (
      // AWS CLI firewall modifications
      re.regex($proc.principal.process.command_line, `(?i)aws\s+ec2\s+(authorize|revoke|create|delete|modify)[\s\-]+(security.group|ingress|egress)`) or
      // GCP gcloud firewall modifications
      re.regex($proc.principal.process.command_line, `(?i)gcloud\s+(compute\s+firewall.rules|compute\s+networks)\s+(create|update|delete|patch)`) or
      // Azure CLI firewall modifications
      re.regex($proc.principal.process.command_line, `(?i)az\s+(network\s+nsg|network\s+firewall|network\s+vnet)\s+(rule\s+)?(create|update|delete|add)`) or
      // Permissive CIDR patterns indicating wide-open rules (0.0.0.0/0 or ::/0)
      re.regex($proc.principal.process.command_line, `(?i)(0\.0\.0\.0\/0|::\/0).*(ingress|inbound|allow|permit|open|any)`) or
      re.regex($proc.principal.process.command_line, `(?i)(ingress|inbound|allow|permit|open|any).*(0\.0\.0\.0\/0|::\/0)`)
    )

    // Correlate both events to the same user principal within a 5-minute window
    $api_call.principal.user.userid = $proc.principal.user.userid

  condition:
    $api_call and $proc

}
